const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='practimals-spelling-v4';
let developerMode=false,developerBackup=null,packDraft=null,packLevel='y2';
let state;try{state=JSON.parse(localStorage.getItem(KEY));}catch{}
if(!state||![4,5,6,7,8,9,10].includes(state.version)||!state.profiles?.length)state={version:4,active:'one',sound:true,profiles:[freshProfile('one','Child 1',7),freshProfile('two','Child 2',10)]};
if(state.version<5){for(const pr of state.profiles){pr.totalGames=pr.week?.games.length||0;pr.voiceStyle='bubbles';pr.eyeColour='violet';pr.schoolResults??=[];if(!pr.palName||pr.palName==='Your pal')pr.palName='Bobble';if(pr.words.length&&pr.words.map(w=>w.word).join()!==SAMPLE_WORDS.map(w=>w.word).join()){(pr.archivedLists??=[]).push({words:pr.words,testDate:pr.week?.testDate});}setWeek(pr,SAMPLE_WORDS.map(w=>({...w})),pr.week?.testDate||nextTestDay(),{newWeek:pr.words.map(w=>w.word).join()!==SAMPLE_WORDS.map(w=>w.word).join()});syncEgg(pr);}state.version=5;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}}
for(const pr of state.profiles){migrateJourney(pr);migrateEggLooks(pr);migrateCorrectRewards(pr);migrateSpecialRewards(pr);migrateVoices(pr,state.version);syncDenMilestones(pr);sanitiseProfile(pr);if(state.version<7&&pr.week&&!pr.week.design.locks.species&&!pr.week.answers.length){pr.species='blob';pr.voiceStyle=null;rememberLook(pr);}if(pr.week){pr.week.announcedBadges??=[];syncEgg(pr);}}state.version=10;state.theme??='stone';try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}
let speechIssue='',speechInFlight=null;
let unlockOffer=null,pausedPractice=null,guideSpeaking=false,activeVoice=null;
const alienSpeaker=new AlienSpeaker({onBlocked:message=>{speechIssue=message;showSpeechIssue();},onStatus:text=>document.querySelectorAll('[data-voice-status]').forEach(el=>el.textContent=text),onTalk:(active,level)=>document.dispatchEvent(new CustomEvent('pal-speaking',{detail:active?{level,guide:guideSpeaking,voiceStyle:activeVoice}:false}))});
let denGame=null,cleanDen=null,cleanBaby=null,cleanHatch=null,cleanFit=null,chosenPortrait=null,hatchTimer=null,speechDelay=null;
let creativePaper='sky',sentencePreviewJob=0,sentencePreviewTimer=null,chosenAlbumWeek=null,babyHelloTimer=null;
let hatchScene=null,demoBaby=null,lastStart=null;
let listSpeaking=false,listSpeechToken=0;
let pendingQuestion=null,speechRun=0,retryAdvanceTimer=null;
let view=['themes','studio','developer','packs','week-preview'].includes(new URLSearchParams(location.search).get('view'))?new URLSearchParams(location.search).get('view'):'home',selectedWord=null,session=null,test=null,parentOpen=false,parentMessage='',chosenBaby=null,cleanPal=null,cleanModels=null,drawing=false,canvasDirty=false,creativeWord=null,photoUrl='',toastTimer;
const p=()=>state.profiles.find(x=>x.id===state.active)||state.profiles[0];
function save(){if(developerMode)return;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notify('This browser cannot save more. New progress will last only for this session.');}}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4300);}
function showSpeechIssue(){let panel=$('#speech-recovery');const disabled=['game','test'].includes(view)&&(!state.sound||state.spokenQuestions===false);if(!speechIssue&&!disabled){panel?.remove();return;}if(!panel){panel=document.createElement('section');panel.id='speech-recovery';panel.className='speech-recovery';panel.setAttribute('role','status');panel.innerHTML='<span></span><button class="secondary">Enable speech & hear my word ♫</button>';document.querySelector('main')?.prepend(panel);panel.querySelector('button').onclick=()=>{state.sound=true;state.spokenQuestions=true;save();speechIssue='';alienSpeaker.unlock();speak(questionText()||wordSpeech(p().words[0]?.word||'hello'));};}panel.querySelector('span').textContent=speechIssue||'Spoken questions are off. Tap to hear your Spelloid.';}
function speak(text,{quiet=false}={}){guideSpeaking=selectedVoice(p())===DEFAULT_VOICE;const payload=guideSpeaking?{parts:(typeof text==='string'?[{text}]:text?.parts||[]).map(part=>({...part,clear:true}))}:text;activeVoice=selectedVoice(p());const run=speechRun;return alienSpeaker.say(payload,activeVoice).then(ok=>{if(run===speechRun&&ok){speechIssue='';showSpeechIssue();}return ok;});}
function cancelSpeech(){listSpeechToken++;listSpeaking=false;updateListButton();speechRun++;speechInFlight=null;clearTimeout(speechDelay);alienSpeaker.cancel();document.dispatchEvent(new CustomEvent('pal-speaking',{detail:false}));}

function updateListButton(){const button=$('#hear-all');if(button){button.textContent=listSpeaking?'■ Stop list':'♫ Hear list';button.setAttribute('aria-pressed',String(listSpeaking));button.setAttribute('aria-label',listSpeaking?'Stop hearing my list':'Hear my list');}}
function toggleHearList(){if(listSpeaking){cancelSpeech();return;}cancelSpeech();const token=++listSpeechToken;listSpeaking=true;updateListButton();speak({parts:p().words.map(w=>({text:w.word,clear:true,pause:260}))}).finally(()=>{if(token===listSpeechToken){listSpeaking=false;updateListButton();}});}
function questionText(){if(view==='test'&&test&&!test.result)return spellingSpeech(test.items[test.index]);if(!session||session.finished)return null;const w=view==='creative'?p().words.find(x=>x.word===creativeWord):session.items[session.index];if(!w)return null;if(['study','listen','build','letters'].includes(session.method))return spellingSpeech(w);if(session.method==='meaning')return{parts:[{text:'Which word matches the meaning?',pause:250},{text:w.meaning||'Ask a grown-up to add a meaning.',clear:true}]};if(session.method==='gap')return{parts:[{text:'Which word fits the sentence?',pause:250},{text:gapFor(w).replaceAll('_____','blank'),clear:true}]};return{gap:'Which word fits? '+gapFor(w).replaceAll('_____','blank'),meaning:'Which of your weekly words means '+(w.meaning||'the word your grown-up describes')+'?',sentence:'Let’s make a sentence using '+w.word+'!',draw:'What picture could help us remember '+w.word+'?'}[session.method];}

function speakPending(){if(unlockOffer||!['game','test','creative'].includes(view))return;const payload=pendingQuestion;if(!payload||speechInFlight===payload||!state.sound||state.spokenQuestions===false)return;speechInFlight=payload;speak(payload,{quiet:true}).then(ok=>{if(speechInFlight===payload)speechInFlight=null;if(ok&&pendingQuestion===payload)pendingQuestion=null;if(view==='game'&&session?.retryExhausted)scheduleRetryAdvance();});}

function go(next){specialSuitDraft=null;if(next==='wall')next='egg';cancelPhotoReader();if(view==='pal'&&next!=='pal'&&creationDraft?.clothes)creationDraft.clothes={};clearTimeout(babyHelloTimer);clearTimeout(sentencePreviewTimer);sentencePreviewJob++;if(next==='pal'&&['game','test'].includes(view)){openCustomiser();return;}cancelSpeech();unlockOffer=null;clearTimeout(hatchTimer);hatchTimer=null;if(hatchScene)hatchScene=null;if(next!=='egg')demoBaby=null;pendingQuestion=null;document.dispatchEvent(new CustomEvent('pal-speaking',{detail:false}));view=next;if(next!=='parents')parentOpen=false;session=null;test=null;render();if(next==='home')landAt(!p().week?.started?$('.pledge-card'):$('.dashboard-intro'));else scrollTo({top:0,behavior:'smooth'});}
function header(){return `<header><a class="brand" href="#" data-go="home"><span class="brand-symbol spelloid-brand" aria-hidden="true"><img src="brand-mark.svg" alt=""></span>spelloids<small>little practice, big confidence</small></a><nav aria-label="Main navigation">${[['home','Spelling Hub'],['pal','Your Spelloid'],['den','Secret den'],['scrapbook','Scrapbook'],['egg','Nursery'],['results','Test results']].map(([key,label])=>`<button class="nav-link ${(view===key||view==='album'&&key==='scrapbook')?'active':''}" data-go="${key}">${label}</button>`).join('')}</nav><div class="header-tools"><button class="sound-button" id="sound" aria-label="${state.sound?'Mute':'Enable'} creature sounds">♫ ${state.sound?'On':'Off'}</button><button class="grownups" data-go="themes">Colours</button><button class="grownups" data-go="parents">Grown-ups ↗</button></div></header>`;}
function weekLine(){return p().week?`<div class="week-line"><span>${esc(p().name)}’s weekly spellings</span><strong>${p().words.length} words</strong><span>School test: ${formatDay(p().week.testDate)}</span></div>`:'';}
function render(){clearTimeout(retryAdvanceTimer);sanitiseProfile(p());cleanDen?.();cleanHatch?.();cleanHatch=null;cleanBaby?.();cleanFit?.();cleanPal?.();cleanModels?.();document.documentElement.dataset.theme=state.theme;stopPalInteraction();drawing=false;const pages={home:homePage,pal:palPage,egg:eggPage,parents:parentsPage,game:gamePage,creative:creativePage,test:testPage,scrapbook:scrapbookPage,hatching:hatchingPage,themes:()=>themeOptions(p()),den:denPage,play:denPlayPage,wall:nurseryPage,results:resultsPage,studio:studioPage,packs:packsPage,developer:developerPage,album:()=>scrapbookPage(chosenAlbumWeek),'week-preview':weekPreviewPage};$('#app').innerHTML=header()+(developerMode?'<div class="developer-banner"><strong>TEST PLAYGROUND</strong> A copy of your progress. Real learning is unchanged. <button class="small-button" data-go="developer">Test tools</button><button class="small-button" id="exit-developer">Leave test mode</button></div>':'')+`<main>${!['parents','album'].includes(view)?weekLine():''}${(pages[view]||homePage)()}</main><footer>Only this week’s words. Plenty of ways to practise.<span>Made for ages 5–10</span></footer>${unlockMarkup()}`;if(view==='pal'&&$('.setup-launch')&&!(pausedPractice?.profileId===p().id&&pausedPractice?.weekId===p().week?.id)){$('.page-intro').classList.add('with-setup-launch');$('.page-intro').append($('.setup-launch'));}setSound(state.sound);setCharacterVoice(p().voiceStyle);bindCommon();cleanPal=bindPalInteractions();cleanModels=mountMonsters();fillBabyPortraits();if(view==='game')bindGame();if(view==='creative')bindCreative();if(view==='parents')bindParents();if(view==='test')bindTest();bindV5();bindV6();bindV7();bindV8();bindV9();bindSpecialSuits();fillMediaImages();cleanFit=fitWords();document.querySelectorAll('input:not([type]),input[type=text],textarea').forEach(el=>{el.setAttribute('autocorrect','off');el.setAttribute('autocapitalize','none');el.setAttribute('autocomplete','off');el.setAttribute('spellcheck','false');el.setAttribute('data-gramm','false');el.setAttribute('data-enable-grammarly','false');});updateListButton();speakPending();showSpeechIssue();scheduleRetryAdvance();}
function profilePicker(){return `<label class="profile-picker">Practising as<select id="profile">${state.profiles.map(x=>`<option value="${x.id}" ${x.id===p().id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`;}
function palCard(){const pr=p(),level=badgeCount(pr),next=badgesFor(pr)[level],creature=palMarkup(pr).replace('<div class="pal-actions">','<details class="pal-play-menu"><summary>Play together</summary><div class="pal-actions">').replace('</div><p data-voice-status','</div></details><p data-voice-status');return `<aside class="companion-card dashboard-spelloid"><div class="companion-name"><span>Your Spelloid</span><h2>${esc(pr.palName)}</h2></div>${creature}<div class="dashboard-rewards"><strong>${level} / 8 badges</strong><p>${!pr.week?.started?'Ready for your first badge?':next?Math.max(0,next.at-weekAnswers(pr))+' correct challenges to your next badge':'All eight earned. Lovely work!'}</p></div><button class="text-button" data-go="pal">Customise your Spelloid →</button>${denAccess(pr,localDay()).open?'<button class="secondary" data-go="den">Secret Den is open →</button>':''}</aside>`;}

function dashboardMethod(key,extra=false){const m=METHODS[key],status=extra?null:moduleStatus(p(),key),title={gap:'Missing word',meaning:'Match the meaning'}[key]||m.title;return `<button class="method-card mode-${key} ${status?.complete?'module-complete':''}" data-method="${key}" aria-label="${esc(m.title)}${extra?' · creative extra':', '+status.passed+' of '+p().words.length+' complete'}"><span class="method-icon">${methodIcon(key)}</span><div><h3>${esc(title)}</h3><small>${extra?'Make it your own':status.complete?'All done · extra practice':status.passed+' / '+p().words.length+' complete'}</small></div><span class="method-arrow" aria-hidden="true">→</span></button>`;}
function homePage(){const pr=p(),practised=pr.words.filter(w=>wordProgress(pr,w.word)===6).length;return `${!pr.week?.started?'<section class="pledge-card"><span class="eyebrow">BADGE 1 · READY TO LEARN</span><h2>A new week. A little beginning.</h2><p>Name your Spelloid, choose its shape and give it a voice.</p><button class="primary" id="start-learning">Choose my Spelloid →</button></section>':''}<section class="page-intro dashboard-intro"><div><span class="eyebrow">YOUR WORDS. YOUR SPELLOID. YOUR WEEK.</span><h1>Your Spelling Hub.</h1></div><div class="home-actions">${profilePicker()}</div></section>
 ${pr.words.length?`${baselineSuggestion()}<div class="home-layout weekly-dashboard"><section class="word-panel" aria-labelledby="weekly-words-title"><div class="section-heading"><div><h2 id="weekly-words-title">Your spellings</h2><p>${practised} / ${pr.words.length} green</p></div><button class="small-button" id="hear-all" aria-label="Hear my list">♫ Hear list</button></div><div class="word-grid">${pr.words.map((w,i)=>`<button class="word-chip ${wordProgress(pr,w.word)===6?'tried':''} ${selectedWord===w.word?'selected':''}" data-word="${esc(w.word)}" aria-label="${esc(w.word)}, ${wordProgress(pr,w.word)} of six challenges complete"><small>${String(i+1).padStart(2,'0')}</small><strong>${esc(w.word)}</strong><span class="word-count" aria-hidden="true">${wordProgress(pr,w.word)===6?'✓':wordProgress(pr,w.word)+'/6'}</span>${challengeIcons(pr,w.word)}</button>`).join('')}</div>${selectedWord?wordDetail(pr.words.find(w=>w.word===selectedWord)):''}</section>
 <section class="practice-section core-practice" aria-labelledby="core-practice-title"><div class="section-heading"><div><h2 id="core-practice-title">Choose a challenge</h2><p>Six lights make a word green.</p></div></div><div class="method-grid">${REQUIRED_METHODS.map(key=>dashboardMethod(key)).join('')}</div></section>${palCard()}
 <section class="creative-extras" aria-labelledby="creative-extras-title"><div class="section-heading"><div><h2 id="creative-extras-title">A little extra creativity</h2><p>For your scrapbook · outside the six green lights.</p></div></div><div class="method-grid">${['sentence','draw'].map(key=>dashboardMethod(key,true)).join('')}</div></section>
 <section class="test-banner"><span class="test-icon" aria-hidden="true">✓</span><div><h2>Try the whole list</h2><p>A whole-list check. Your Secret Den opens when you finish any one challenge module.</p></div><button class="primary" id="start-test">Take a practice test →</button></section></div>`:`<section class="empty-card"><h2>Let’s add your spelling list.</h2><p>A grown-up can add this week’s words. Every challenge will use that list.</p><button class="primary" data-go="parents">Add this week’s spellings →</button></section>`}`;}

function wordDetail(w){if(!w)return'';return `<div class="word-detail"><div><span class="eyebrow">LET’S UNDERSTAND IT</span><h3>${esc(w.word)}</h3><div class="word-checklist">${REQUIRED_METHODS.map(m=>`<span class="${p().week.progress[w.word]?.passed?.includes(m)?'done':''}">${p().week.progress[w.word]?.passed?.includes(m)?'✓':'○'} ${METHODS[m].title}</span>`).join('')}</div><p>${esc(w.meaning||'Ask a grown-up to add a simple meaning for this word.')}</p>${w.sentence?`<p class="example">${esc(w.sentence)}</p>`:''}</div><button class="secondary" data-hear="${esc(w.word)}">♫ Hear it</button></div>`;}
function baselineSuggestion(){const pr=p();if(!pr.week?.started||pr.week.baselineDismissed||matchingPracticeTests(pr).length)return '';return '<section class="baseline-card"><div><span class="eyebrow">OPTIONAL STARTING CHECK</span><h2>See what I know already</h2><p>Try your whole list once. Later, see how much you have learned. No badges, no pressure.</p></div><button class="primary" id="baseline-test">Try a starting check →</button><button class="secondary" id="skip-baseline">Start practising →</button></section>';}
function rewardSummary(){const n=badgeCount(p()),answers=weekAnswers(p()),next=badgesFor(p())[n];return `<div class="reward-summary"><strong>${n} badge${n===1?'':'s'} this spelling set</strong><p>${!p().week?.started?'Badge 1 is waiting. Choose to have a go!':next?answers+' correct challenges · next badge at '+next.at+'.':'All eight badges earned. Lovely dedication!'}</p><div class="badge-track">${badgesFor(p()).map(b=>`<span class="practice-badge ${n>=b.id?'earned':''}" title="Badge ${b.id}${n>=b.id?' · '+b.title:' · surprise to discover'}">✧<small>${b.id}</small></span>`).join('')}</div></div>`;}
function palPage(){return identityPage();}

function eggSVG(egg){const palette=eggPalette(egg),shellId='shell-'+String(egg.id||'preview').replace(/[^a-zA-Z0-9_-]/g,''),lightId=shellId+'-light';const {stage,green,wordCount}=eggProgress(egg),cracks=['M113 64 129 94 118 117 140 143 124 170','M140 143 174 125 169 100 189 86','M124 170 96 183 106 207 85 226','M124 170 155 191 149 215 180 244','M155 191 183 181 207 201'];const density=egg.wordCount?Math.max(0,Math.min(1,green/Math.max(1,wordCount))):stage/5;return `<svg viewBox="0 0 280 330" class="egg-illustration stage-${stage}" role="img" aria-label="Egg: ${green} of ${wordCount} words green; crack stage ${stage} of 5"><defs><radialGradient id="${shellId}" cx=".28" cy=".2" r=".85"><stop stop-color="${palette.light}"/><stop offset=".38" stop-color="${palette.mid}"/><stop offset=".78" stop-color="${palette.shade}"/><stop offset="1" stop-color="${palette.edge}"/></radialGradient><radialGradient id="${lightId}"><stop stop-color="#fff7cc" stop-opacity=".8"/><stop offset="1" stop-color="#fff7cc" stop-opacity="0"/></radialGradient></defs><ellipse cx="140" cy="301" rx="91" ry="17" fill="#4d3a442b"/><path d="M140 30C95 30 43 151 47 210c4 63 44 83 93 83s89-20 93-83C237 151 185 30 140 30Z" fill="url(#${shellId})" stroke="${palette.edge}" stroke-width="3"/><ellipse cx="103" cy="127" rx="36" ry="62" transform="rotate(20 103 127)" fill="url(#${lightId})"/>${[[89,136,12],[174,100,9],[185,214,17],[102,236,10],[144,179,14],[72,191,7]].map(([x,y,r])=>`<ellipse cx="${x}" cy="${y}" rx="${r}" ry="${r*.8}" fill="#ae71573a" stroke="#fff0bd55" stroke-width="1"/>`).join('')}${cracks.slice(0,stage?Math.max(1,Math.ceil(density*5)):0).map((d,i)=>`<g><path d="${d}" fill="none" stroke="#ffecc5" stroke-width="${4+density*4}" stroke-linecap="round"/><path d="${d}" fill="none" stroke="#684840" stroke-width="${1.8+density*3}" stroke-linecap="round" stroke-linejoin="round"/><path d="${d}" fill="none" stroke="#ffe3a7" opacity="${density*.7}" stroke-width="1"/></g>`).join('')}${Array.from({length:Math.min(20,green)},(_,i)=>`<path d="M${76+i%5*28} ${118+Math.floor(i/5)*36}l-5 8 7 7" stroke="#79513f" stroke-width="1.3" opacity=".7" fill="none"/>`).join('')}${stage>=4?'<path d="M115 182q25-15 49 0" stroke="#fff3ba" stroke-width="5" fill="none" class="egg-glow"/>':''}</svg>`;}
function eggPage(){return nurseryPage();}

function startMode(method){cancelSpeech();if(['meaning','gap'].includes(method)&&p().words.some(w=>method==='meaning'?!w.meaning:!w.sentence)){palNotice('A grown-up needs to finish our '+(method==='meaning'?'meanings':'example sentences')+' first. We can still practise spelling in the other rounds.');return;}if(!setupStatus(p()).ready){go('pal');return;}creativePaper='sky';if(!p().week?.started){go('pal');return;}if(!METHODS[method]||!p().words.length){notify('Add this week’s spelling list first.');return;}selectedWord=null;if(['sentence','draw'].includes(method)){creativeWord=shuffle(p().words)[0].word;session={method};view='creative';}else{const items=orderedWords(p(),method);if(items.length>1&&items[0].word===lastStart)items.push(items.shift());lastStart=items[0]?.word;session={method,items,extraPractice:moduleStatus(p(),method).complete,skipped:[],index:0,answer:'',feedback:'',answered:false,revealed:false,covered:false,built:[],letters:[],correct:0};view='game';}pendingQuestion=questionText();render();landAt($('.game-card')||$('.creative-card'));}
function gamePage(){if(session.finished)return finishPage();const m=METHODS[session.method],word=session.items[session.index],pr=p(),previous=pr.week.rounds[session.method],done=session.index;
 const choices=['gap','meaning'].includes(session.method),tiles=session.method==='build'||!choices&&pr.support==='tiles'&&['listen','study'].includes(session.method);
 if(!session.letters.length){session.letters=[...word.word].map((letter,id)=>({letter,id}));for(let i=session.letters.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[session.letters[i],session.letters[j]]=[session.letters[j],session.letters[i]];}}
 if(choices&&!session.choices)session.choices=choicesFor(pr,word.word);
 const study=session.method==='study'&&!session.covered&&!session.answered;
 const clue=session.method==='gap'?gapFor(word):session.method==='meaning'?word.meaning||'Ask a grown-up to describe this word.':'';
 return `<div class="activity-header"><strong>${m.title}</strong><span>${Math.min(session.items.length,done+1)} / ${session.items.length} this round</span></div><div class="activity-progress"><span style="width:${done/session.items.length*100}%"></span></div><div class="game-layout"><section class="game-card" data-round-word="${esc(word.word)}">${creationTools()}${session.nurseryBaby?`<div class="learning-baby">♥ ${esc((demoBaby||pr.babies.find(b=>b.id===session.nurseryBaby))?.name||'Baby')} is learning with you. A correct word teaches your baby too!</div>`:''}<span class="eyebrow">${session.extraPractice?'EXTRA PRACTICE · NO NEW CREATION POINTS':moduleStatus(pr,session.method).remaining.length+' WORDS LEFT IN THIS MODULE'}</span><h1>${{study:'Look. Say. Cover. Try.',listen:'Listen, then have a go.',build:'Build your weekly word.',letters:'What’s hiding in this word?',gap:'What’s the missing word?',meaning:'Which word matches?'}[session.method]}</h1><p class="activity-instructions">${esc(m.description)}</p>${choices?`<p class="question-clue">${esc(clue)}</p>`:session.method==='study'?`<div class="study-board ${session.covered&&!session.answered?'is-covered':''}"><div class="study-word" ${session.covered&&!session.answered?'aria-hidden="true"':''}>${esc(word.word)}</div><div class="word-cover" aria-hidden="true"><span>✋</span> Shhh… I’ve got it!</div></div><p class="word-meaning">${esc(word.meaning||'Say your word aloud with a grown-up.')}</p>`:session.method==='letters'?`<div class="masked-word">${esc([...word.word].map((ch,i)=>/[a-z]/.test(ch)&&i%3!==0?'_':ch).join(' '))}</div><p class="word-meaning">${esc(word.meaning||'Listen to the word, then fill in the letters.')}</p>`:session.method==='build'?`<p class="word-meaning">${esc(word.meaning||'Listen to the word, then arrange the letters.')}</p>`:'<p class="word-meaning">Listen as often as you like. Take your time.</p>'}<button class="listen-button" id="hear-word">♫ ${study?'Hear it':'Hear the word'}</button>${study?'<button class="primary cover-button" id="cover-word">I’ve looked. Cover it →</button>':session.answered?`<div class="revealed-word">${esc(word.word)}</div>`:choices?`<div class="answer-choices">${session.choices.map(w=>`<button data-answer="${esc(w)}">${esc(w)}</button>`).join('')}</div>`:tiles?`<div class="letter-slots">${session.built.map(id=>`<button data-remove="${id}">${esc(session.letters.find(x=>x.id===id).letter)}</button>`).join('')}${Array.from({length:Math.max(0,word.word.length-session.built.length)},()=>'<span>·</span>').join('')}</div><div class="letter-bank">${session.letters.map(x=>`<button data-letter="${x.id}" ${session.built.includes(x.id)?'disabled':''}>${esc(x.letter)}</button>`).join('')}</div>`:`<label class="field-label" for="answer">${session.method==='letters'?'Type the whole word':'Your spelling'}</label><input class="answer-input" id="answer" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(session.answer)}" placeholder="Have a go…">`}<p class="feedback ${session.answered&&!session.revealed?'success':''}" id="feedback" role="status">${esc(session.feedback||'Trying is how we learn. I’m right here.')}</p><div class="game-buttons">${session.answered?`<button class="primary" id="next-word">${session.index===session.items.length-1?'Finish this round':'Next weekly word'} →</button>`:!study?`${!choices?`<button class="primary" id="check">${session.mistakes?'Try again →':'Let’s check →'}</button>`:''}<button class="text-button" id="show-word">Show me, then I’ll try again later</button>`:''}</div><button class="text-button skip-word" id="skip-word" ${session.answered?'disabled':''}>Skip this word for now →</button><p class="activity-note">${session.extraPractice?'This module is already complete. Extra practice adds no creation rewards.':'Passed words stay out of this module. Skipped words will be ready next time.'}</p></section><aside class="game-companion">${palMarkup(pr,{prompt:session.feedback||({study:study?'Look at our word and say it with me.':'Can you spell it now it’s covered?',listen:'Can you spell the word I’m saying?',build:'Can you build my word with these letters?',letters:'Can you find my missing letters?',gap:'Can you choose the word missing from my sentence?',meaning:'Which weekly word matches my clue?'}[session.method])})}<button class="hub-return" data-go="home">← Back to Spelling Hub</button></aside></div>`;}
function bindGame(){if(session.finished)return;const word=session.items[session.index];$('#hear-word').onclick=()=>speak(['gap','meaning'].includes(session.method)?questionText():wordSpeech(word.word));$('#cover-word')?.addEventListener('click',()=>{session.covered=true;pendingQuestion=wordSpeech(word.word);render();});$('#answer')?.addEventListener('input',e=>session.answer=e.target.value);$('#answer')?.addEventListener('keydown',e=>{if(e.key==='Enter')checkAnswer();});$('#check')?.addEventListener('click',()=>checkAnswer());document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>checkAnswer(b.dataset.answer));document.querySelectorAll('[data-letter]').forEach(b=>b.onclick=()=>{session.built.push(Number(b.dataset.letter));render();});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{session.built=session.built.filter(x=>x!==Number(b.dataset.remove));render();});$('#show-word')?.addEventListener('click',()=>{session.answered=true;session.revealed=true;session.feedback='Here is the word. We will try it again another time.';recordWord(p(),word.word,session.method,{assisted:true});save();render();});$('#next-word')?.addEventListener('click',()=>advancePractice());$('#skip-word')?.addEventListener('click',()=>{if(!session.answered)session.skipped.push(word.word);advancePractice(true);});}

function checkAnswer(choice){
 if(session.answered)return;
 const word=session.items[session.index],value=(choice??(session.method==='build'||p().support==='tiles'&&['listen','study'].includes(session.method)?session.built.map(id=>session.letters.find(x=>x.id===id).letter).join(''):session.answer)).trim().toLowerCase();
 if(!value){$('#feedback').textContent='Have a go, or ask for the word to be shown.';return;}
 const before=badgeCount(p()),correct=value===word.word,outcome=answerAttempt(session.mistakes,correct);session.mistakes=outcome.mistakes;
 recordWord(p(),word.word,session.method,{correct});save();
 if(correct){const learner=demoBaby?.id===session.nurseryBaby?demoBaby:p().babies.find(b=>b.id===session.nurseryBaby);if(learner){learner.learnedWords=[...new Set([...(learner.learnedWords||[]),word.word])];if(!demoBaby)save();}session.answered=true;session.correct++;session.feedback=feedbackPhrase('correct',session.feedbackIndex||0);session.feedbackIndex=(session.feedbackIndex||0)+1;soundEffect('celebrate');}
 else if(outcome.status==='retry'){session.answer='';session.built=[];session.feedback=feedbackPhrase('retry',session.retryIndex||0);session.retryIndex=(session.retryIndex||0)+1;}
 else{session.answered=true;session.revealed=true;session.retryExhausted=true;session.skipped=[...new Set([...session.skipped,word.word])];session.feedback=feedbackPhrase('next',session.nextIndex||0);session.nextIndex=(session.nextIndex||0)+1;}
 captureUnlock(before);pendingQuestion=session.feedback;render();
}

function finishPage(){const creative=['draw','sentence'].includes(session.method),status=creative?null:moduleStatus(p(),session.method);return `<section class="finish-card"><span class="eyebrow">${creative?'A WORD YOU MADE YOUR OWN':session.extraPractice?'EXTRA PRACTICE · JUST FOR FUN':'YOUR PROGRESS IS SAVED'}</span><h1>${creative?'You made that word your own.':session.extraPractice?'A little extra practice. Lovely work!':status.complete?'Every word passed in this module!':'A good little practice round.'}</h1><p>${creative?'Your creation is saved in your scrapbook.':session.extraPractice?'This replay does not earn new creation points or badges.':status.complete?'You can replay the full list for extra practice whenever you like.':status.remaining.length+(status.remaining.length===1?' word is':' words are')+' still ready for another go. Skipped and shown words stay in the module.'}</p>${creationTools()}${palMarkup(p())}${!creative&&!status.complete?`<button class="primary" data-method="${session.method}">Try the remaining ${status.remaining.length} words →</button>`:''}${!creative&&status.complete?`<button class="secondary" data-method="${session.method}">Extra practice — no new rewards</button>`:''}${p().eggs.some(e=>e.id===p().week.eggId&&!e.hatched&&eggProgress(e).ready)?'<div class="reward-callout"><strong>Our egg is ready!</strong><button class="primary" data-go="egg">Help our baby hatch →</button></div>':''}<div class="game-buttons"><button class="primary" data-go="home">Spelling Hub →</button><button class="secondary" data-update-pal>Update my pal</button></div></section>`;}

function creativePage(){if(session.finished)return finishPage();const entry=p().words.find(x=>x.word===creativeWord)||p().words[0],draw=session.method==='draw';return `<div class="activity-header"><strong>${METHODS[session.method].title}</strong></div><section class="page-intro"><div><span class="eyebrow">CHOOSE ONLY FROM THIS WEEK’S WORDS</span><h1>${draw?'What does your word look like?':'Give your word a sentence.'}</h1></div><label class="profile-picker">My weekly word<select id="creative-word">${p().words.map(w=>`<option ${w.word===entry.word?'selected':''}>${esc(w.word)}</option>`).join('')}</select></label></section><div class="creative-layout"><section class="creative-card"><h2>${esc(entry.word)}</h2><p class="word-meaning">${esc(entry.meaning||'Talk about what this word means with a grown-up.')}</p>${paperPickerMarkup()}${draw?`<div class="drawing-tools">${['#70579b','#429784','#de876c','#4e8abb','#353343','#ffffff','#f4d774'].map((colour,i)=>`<button class="pen ${i===0?'chosen':''}" style="background:${colour}" data-pen="${colour}" aria-label="${['Purple','Green','Orange','Blue','Dark','White','Gold'][i]} pen"></button>`).join('')}<div class="draw-tool-row">${[['pen','✎ Pen'],['brush','▰ Brush'],['highlight','▱ Highlighter'],['eraser','▱ Rubber'],['star','★ Stamp'],['heart','♥ Stamp']].map(([key,label])=>`<button class="small-button ${key==='pen'?'chosen':''}" data-tool="${key}" aria-pressed="${key==='pen'}">${label}</button>`).join('')}<label>Size <input type="range" id="brush-size" min="3" max="50" value="8"></label><button class="small-button" id="undo-draw">↶ Undo</button><button class="small-button" id="redo-draw">↷ Redo</button><button class="text-button" id="clear-canvas">Clear</button></div></div><canvas id="drawing" width="900" height="560" aria-label="Draw a picture for your selected spelling word"></canvas>`:`<label class="field-label" for="sentence">Use “${esc(entry.word)}” in your own sentence</label><label class="field-label" for="sentence-font">My writing style</label><select id="sentence-font">${Object.entries(SENTENCE_FONTS).map(([id,font])=>`<option value="${id}">${font.title}</option>`).join('')}</select><textarea id="sentence" class="sentence-writing" rows="5" maxlength="350" placeholder="My sentence…"></textarea><button class="text-button" id="starter">Help me get started</button><div class="sentence-preview"><img id="sentence-preview" alt="Your sentence picture preview"></div>`}<p class="feedback" id="creative-feedback" role="status">${draw?'Draw with a finger or mouse. Tell someone about your idea.':'A grown-up can help you talk about your sentence. Your pal doesn’t grade grammar.'}</p><button class="primary" id="save-creation">Keep it in my scrapbook →</button><button class="text-button" data-go="scrapbook">See my scrapbook</button></section><aside class="game-companion">${palMarkup(p(),{prompt:session.method==='draw'?'What could you draw to help us remember this word?':'Can you tell me a sentence using this word?'})}<button class="hub-return" data-go="home">← Back to Spelling Hub</button></aside></div>`;}
function containsWord(sentence,word){return sentence.toLowerCase().split(/[^a-z'-]+/).includes(word);}
function bindCreative(){if(session.finished)return;canvasDirty=false;$('#creative-word').onchange=e=>{creativeWord=e.target.value;pendingQuestion=questionText();render();};const canvas=$('#drawing');if(canvas)bindDrawing(canvas);$('#starter')?.addEventListener('click',()=>{$('#sentence').value='I noticed ';$('#sentence').focus();});$('#sentence-font')?.addEventListener('change',e=>{$('#sentence').style.fontFamily=SENTENCE_FONTS[e.target.value].family;});if($('#sentence'))$('#sentence').style.fontFamily=SENTENCE_FONTS.handwriting.family;$('#save-creation').onclick=async()=>{const sentence=$('#sentence')?.value.trim()||'';if(session.method==='draw'&&!canvasDirty){palNotice('Let’s add a little drawing before we keep it.');return;}if(session.method==='sentence'&&!containsWord(sentence,creativeWord)){palNotice(`Can you include “${creativeWord}” in your sentence?`);return;}const profile=p(),weekId=profile.week.id,creationSession=session,savedWord=creativeWord,method=session.method,font=$('#sentence-font')?.value||'handwriting',background=creativePaper;$('#save-creation').disabled=true;const image=method==='sentence'?await sentencePicture(sentence,font,{background,word:savedWord}):drawingPicture(canvas,background);if(profile!==p()||profile.week.id!==weekId||view!=='creative'||session!==creationSession||creativeWord!==savedWord)return;let artId=null;try{artId=await keepMedia(image,{testMode:developerMode});}catch{}if(profile!==p()||profile.week.id!==weekId||view!=='creative'||session!==creationSession)return;const beforeSpecial=profile.week.specialSuitAward;keepCreation(profile,{word:savedWord,method,sentence,font,background,image:artId?null:image,artId,day:localDay()});recordWord(p(),creativeWord,session.method,{correct:true});const result=completeWord(p(),creativeWord,session.method);session.finished=true;session.credited=result.credited;save();soundEffect('celebrate');render();if(!beforeSpecial&&profile.week.specialSuitAward)notify(SPECIAL_SUITS.find(s=>s.id===profile.week.specialSuitAward).name+' unlocked! Your special suit is yours to keep.');};}
function scrapbookPage(weekId=null){const archived=weekId&&weekId!==p().week?.id,items=scrapbookFor(p(),weekId||p().week?.id),frame=p().portraits.find(f=>f.weekId===weekId),cycle=p().archivedCycles?.find(c=>c.week.id===weekId);return `<section class="page-intro"><div><span class="eyebrow">${archived?'A SPELLING SET TO REMEMBER':'WORDS YOU’VE MADE YOUR OWN'}</span><h1>${archived?esc(frame?.adult.palName||cycle?.look.palName||'Your earlier pal')+'’s scrapbook.':'Your spelling scrapbook.'}</h1><p>${archived?'Saved pictures and sentences from this spelling set.':'This spelling set’s pictures and sentences. Earlier books live in the nursery’s family pictures.'}</p></div><button class="secondary" data-go="${archived?'egg':'home'}">${archived?'Back to the nursery':'My weekly words'} →</button></section>${!archived?specialRewardMarkup():''}<div class="scrapbook-grid">${items.length?items.map(scrapbookCard).join(''):'<section class="empty-card"><h2>A little room for your ideas.</h2><p>Draw a word or write a sentence to make your first scrapbook picture.</p><button class="primary" data-go="home">Choose a word →</button></section>'}</div>`;}
function startTest(){cancelSpeech();if(!setupStatus(p()).ready){go('pal');return;}if(!p().week?.started){go('pal');return;}if(!p().words.length){notify('Add your weekly list first.');return;}test={extraPractice:false,items:shuffle(p().words).map(w=>({...w})),weekId:p().week.id,index:0,answers:[]};view='test';pendingQuestion=questionText();render();landAt($('.test-card'));}
function testPage(){if(test.result){const r=test.result;return `<section class="finish-card"><span class="eyebrow">YOU GAVE THE WHOLE LIST A GO</span><h1>${r.score===r.total?'Every word. Well done!':'Look what you’re learning.'}</h1><strong class="test-score">${r.score} / ${r.total}</strong><p>Saved in Test results · ${r.kind==='baseline'?'Your starting check':'Progress check'}${Number.isFinite(r.change)?' · '+(r.change>=0?'+':'')+r.change+' since your starting check':''}</p><button class="secondary" data-go="results">See my test results →</button><div class="den-result ${denAccess(p(),localDay()).open?'won':''}"><h2>${denAccess(p(),localDay()).open?'✧ Secret Den unlocked!':'A few words to practise together'}</h2><p>${denAccess(p(),localDay()).open?'Your den stays open for this spelling set. Your pal is ready to play!':'Complete every word in one challenge module to open your den.'}</p>${denAccess(p(),localDay()).open?'<button class="primary" data-go="den">Enter my Secret Den →</button>':''}</div><p>${r.score===r.total?'That’s a full-mark practice test. Your hard work is showing.':'Try the tricky words again when you’re ready. No rush, and no lost rewards.'}</p><div class="test-results">${r.results.map(x=>`<div class="${x.correct?'correct':''}"><span>${x.correct?'✓':'↻'}</span><strong>${esc(x.word)}</strong><span>${x.correct?'Remembered!':x.answer==='— skipped —'?'Skipped this time':`You wrote: ${esc(x.answer)}`}</span></div>`).join('')}</div><div class="game-buttons"><button class="primary" data-go="home">Back to my weekly words →</button><button class="secondary" data-go="egg">Check on my egg</button></div></section>`;}
return `<div class="activity-header"><strong>Whole-list practice test</strong><span>${test.index+1} / ${test.items.length}</span></div><div class="game-layout"><aside class="game-companion">${palMarkup(p(),{prompt:`Ready for word ${test.index+1}? Listen to me, then have a go.`})}<button class="hub-return" data-go="home">← Back to Spelling Hub</button></aside><section class="game-card test-card"><span class="eyebrow">ALL ${test.items.length} WORDS FROM YOUR WEEKLY LIST</span><h1>One word at a time.</h1><p>Listen, then spell it. One attempt per word. No hints or badges: this is a check of what you know.</p><button class="listen-button" id="hear-test">♫ Hear word ${test.index+1}</button><p class="hint">A grown-up can read word ${test.index+1} from your list if speech isn’t available.</p><label class="field-label" for="test-answer">My spelling</label><input id="test-answer" ${test.pendingAnswer!==undefined?'disabled':''} class="answer-input" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Have a go…"><button class="text-button skip-word" id="skip-test-word" ${test.pendingAnswer!==undefined?'disabled':''}>Skip this word →</button><p class="feedback" id="test-feedback" role="status">${esc(test.feedback||'Take your time. Each answer is saved once; results appear at the end.')}</p><button class="primary" id="test-next" ${test.pendingAnswer!==undefined?'disabled':''}>${test.index===test.items.length-1?'Finish my practice test':'Save and next word'} →</button></section></div>`;}
function bindTest(){if(test.result)return;$('#hear-test').onclick=()=>speak(wordSpeech(test.items[test.index].word));$('#test-next').onclick=()=>submitTestAnswer();$('#skip-test-word').onclick=()=>submitTestAnswer(true);$('#test-answer').onkeydown=e=>{if(e.key==='Enter')submitTestAnswer();};}
function submitTestAnswer(skip=false){if(!test||test.result)return;const answer=skip?'— skipped —':$('#test-answer').value.trim();if(!answer){$('#test-feedback').textContent='Have a go, or skip this word.';return;}finishTestWord(answer);}
function finishTestWord(answer){
 if(!test||test.result)return;cancelSpeech();test.answers.push(answer);test.index++;test.mistakes=0;test.feedback='';delete test.pendingAnswer;
 if(test.index===test.items.length){try{test.result=markTest(p(),test.answers,test.weekId,test.items.map(w=>w.word));soundEffect('celebrate');}catch(error){notify(error.message);go('home');return;}}
 save();pendingQuestion=test.result?'Your result is saved. Well done for giving the whole list a go.':questionText();render();
}
function scheduleRetryAdvance(){
 clearTimeout(retryAdvanceTimer);if(unlockOffer||(state.sound&&speechInFlight))return;
 const active=p(),weekId=active.week?.id,currentSession=session,currentTest=test;
 if(view==='game'&&session?.retryExhausted&&session.answered&&!session.finished){const index=session.index;retryAdvanceTimer=setTimeout(()=>{if(view==='game'&&!unlockOffer&&p()===active&&p().week?.id===weekId&&session===currentSession&&session.index===index)advancePractice(true);},1800);}
 else if(view==='test'&&test?.pendingAnswer!==undefined&&!test.result){const index=test.index;retryAdvanceTimer=setTimeout(()=>{if(view==='test'&&!unlockOffer&&p()===active&&p().week?.id===weekId&&test===currentTest&&test.index===index)finishTestWord(test.pendingAnswer);},1800);}
}

function parentsPage(){if(!parentOpen)return `<section class="parent-gate"><span class="eyebrow">A LITTLE MOMENT FOR THE GROWN-UPS</span><h1>Set up this week.</h1><p>Add the actual spelling list, check the meanings and choose the school test date.</p><label class="field-label" for="gate">What is the square root of 144? (√144)</label><input id="gate" inputmode="numeric"><p class="feedback" role="status">${esc(parentMessage)}</p><button class="primary" id="unlock">Open settings →</button><p class="hint">A simple settings check, not a password.</p></section>`;
const pr=p();return `<section class="page-intro"><div><span class="eyebrow">THE WEEKLY LIST IS THE WHOLE POINT</span><h1>This week, made simple.</h1><p>10 spellings for younger learners, or 15–20 for older children. Every game uses this list.</p></div>${profilePicker()}</section><section class="profile-settings"><label class="field-label">Child’s display name<input id="child-name" value="${esc(pr.name)}" maxlength="24"></label><label class="field-label">Age<select id="child-age">${[5,6,7,8,9,10].map(x=>`<option ${x===pr.age?'selected':''}>${x}</option>`).join('')}</select></label><label class="field-label">Spelling support<select id="support"><option value="type" ${pr.support!=='tiles'?'selected':''}>Type the word</option><option value="tiles" ${pr.support==='tiles'?'selected':''}>Letter tiles for hear & spell</option></select></label><button class="secondary" id="save-profile">Save profile</button></section><div class="parent-grid"><section class="settings-card"><h2>Your weekly spellings</h2><button class="secondary" data-go="packs">Choose a curriculum word pack →</button><p>Your 15-word example is saved. One word per line, or separate words with commas. No extra spelling words are added to the games.</p>${pr.archivedLists?.length?'<button class="small-button" id="restore-list">Load my previous list into the editor</button>':''}<label class="field-label" for="words">This week’s list · up to 20 words</label><textarea id="words" rows="10" spellcheck="false">${esc(pr.words.map(w=>w.word).join('\n'))}</textarea><label class="field-label" for="test-date">School spelling-test date</label><input id="test-date" type="date" value="${pr.week?.testDate||nextTestDay()}"><p class="hint">The egg hatches when all words have six challenge lights. Editing a list keeps its current egg; start a new week to get a new egg.</p><div class="game-buttons"><button class="primary" id="save-week">Save list & prepare meanings →</button><button class="new-week-action" id="new-week">Start a new spelling week</button></div><p class="feedback" id="save-feedback" role="status"></p><p class="hint">The bundled glossary works fully offline. Words outside the offline glossary need a grown-up’s meaning and example. No words are sent online.</p>${photoReaderMarkup()}<fieldset><legend>Your Spelloid’s voice</legend><label class="checkbox-label"><input type="checkbox" id="spoken-questions" ${state.spokenQuestions!==false?'checked':''}> Read practice questions aloud</label><button class="secondary" id="preview-voice">♫ Hear the current voice</button><button class="secondary" id="prepare-list-speech">Prepare this week’s spoken words</button><p class="hint">Use this before an iPad lesson with new words. Each word is prepared here and kept on this device, free and offline after the files are saved.</p><button class="secondary" id="prepare-offline-voice">Prepare our voice for offline use</button><p class="hint">${nativeApp?'All voice files are included in this app. New spellings are spoken on this device.':'Voice files stay on this device. Prepare offline speech once before using the website without internet.'}</p><p data-voice-status class="voice-status" role="status"></p><button class="secondary" data-go="studio">Review the new pals & voices →</button><p class="hint">Badge 1 opens the name, shape and voice as soon as your child chooses to learn. Spelling narration is available before that. Speech is generated on this device. The example list and practice packs have ready-made clear recordings. New words can take longer the first time; prepare the offline voice here before a lesson.</p></fieldset></section><section class="settings-card"><h2>Simple meanings, your words</h2>${definitionReport(pr.words)}<p>Edit any suggestion to match your child’s age and the meaning used at school.</p><div class="meaning-list">${pr.words.map((w,i)=>`<article class="meaning-editor" data-review-word="${esc(w.word)}"><h3>${esc(w.word)}</h3><small>${esc(w.meaningSource||'Parent meaning')}${w.meaningAttribution?` · <a href="${esc(w.meaningAttribution)}" target="_blank" rel="noopener noreferrer">Source</a>`:''}${w.meaningLicense?` · ${esc(w.meaningLicense)}`:''}</small>${w.contentDraft?`<details><summary>Earlier text saved for parent review</summary><p>This was not marked as checked. It is not used in practice. You can rewrite a suitable version below.</p><p>${esc(w.contentDraft.meaning)}</p><p>${esc(w.contentDraft.sentence)}</p></details>`:''}<label class="field-label">Simple meaning<input data-meaning="${i}" maxlength="250" value="${esc(w.meaning||'')}" placeholder="Explain the word simply…"></label><label class="field-label">Example sentence using the word<input data-example="${i}" maxlength="250" value="${esc(w.sentence||'')}" placeholder="Used in the missing-word game"></label></article>`).join('')||'<p>Add a list to see the meaning suggestions here.</p>'}</div><button class="secondary" id="save-meanings">Save meanings & sentences</button></section></div><section class="parent-handoff"><div><span class="eyebrow">READY FOR YOUR CHILD?</span><h2>Save, check, then hand over.</h2><p>Your current list and edits will be saved. New spellings get meanings from the offline glossary.</p></div><button class="primary" id="hand-to-child">Spellings ready — hand to child →</button><p id="handoff-feedback" role="status"></p></section>${schoolResultsPanel()}<section class="parent-notes"><h2>What counts as practice?</h2><p>The six spelling and meaning games work through the whole list. Children can pause and resume the remaining words that day. Sentence and drawing activities focus on one chosen weekly word. Badge 1 celebrates starting. Badges grow more slowly through correct, independent answers to different core challenges. Wrong answers, repeats, tests and creative work earn no badge credit. Every available customisation is labelled with its badge. Completed-module replays and skipped or shown answers do not add badge points. Creative work is kept without grading grammar. Ten saved pictures or sentences earn one special body finish per set, across five sets. Earned finishes stay in the collection.</p><p>All six core challenges must be answered correctly for a word to turn green. Showing an answer is useful practice but does not earn that challenge light. All words green unlocks the hatch. School test dates never control the egg. Completing every word in any one of the six core modules opens the Secret Den and its two included games. Den access lasts for the current set. Completing a set and starting another grows the Den library: Word Nest first, then Memory Mates and Monster Bingo. Later cycles add remixes.</p><p>Progress, clothes, drawings and babies save on this device only. There are no school accounts or cloud sync.</p><button class="text-button" data-go="scrapbook">View the scrapbook →</button><button class="secondary" data-go="developer">Developer tools · try a safe test copy →</button><button class="secondary" data-go="week-preview">Preview words & practice side by side →</button></section>`;}
function saveEditor(){for(const [selector,field] of [['[data-meaning]','meaning'],['[data-example]','sentence']])for(const el of document.querySelectorAll(selector)){const w=p().words[Number(el.dataset.meaning??el.dataset.example)],value=el.value.trim();if(value!==String(w[field]||'')){const result=approveWordEdit(w,field,value);if(!result.ok){el.setCustomValidity(result.problem);el.reportValidity();return false;}el.setCustomValidity('');}}return true;}
let photoState={file:null,turns:0,canvas:null,crop:null,text:'',status:'',busy:false},photoController=null;
function photoReaderMarkup(){return `<details class="photo-import" ${photoState.file?'open':''}><summary>Take or choose a spelling-list photo</summary><p>Read the words from a photo, check them, then use them in your list. Printed lists work best; handwriting may need correcting.</p><div class="photo-inputs"><label class="photo-input-label">Take a photo<input id="homework-photo" type="file" accept="image/*" capture="environment" aria-label="Take a photo of the spelling list"></label><label class="photo-input-label">Choose an existing photo<input id="photo-upload" type="file" accept="image/*" aria-label="Choose an existing spelling-list photo"></label></div>${photoState.canvas?`<p class="photo-crop-help">Move and resize the box around just the paper. Leave out the table and any headings. Then read the spellings.</p><div class="photo-crop-stage" id="photo-crop-stage"><img class="homework-photo" src="${photoState.canvas.toDataURL('image/jpeg',.9)}" alt="Your spelling-list photo"><div class="photo-crop-box" id="photo-crop-box" tabindex="0" role="group" aria-label="Selected spelling sheet. Use the crop sliders below or drag to move."><span>Read inside this box</span><i data-crop-handle="resize"></i></div></div><details class="crop-adjust"><summary>Adjust crop precisely</summary>${[['x','Left'],['y','Top'],['w','Width'],['h','Height']].map(([key,label])=>`<label>${label}<input type="range" data-crop-range="${key}" ${photoState.busy?'disabled':''} min="0" max="100" value="${Math.round((photoState.crop?.[key]||0)*100)}"></label>`).join('')}</details><div class="photo-actions"><button class="secondary" id="rotate-photo" ${photoState.busy?'disabled':''}>↻ Rotate photo</button><button class="primary" id="read-photo" ${photoState.busy?'disabled':''}>${photoState.busy?'Reading…':'Read the spellings'}</button><button class="text-button" id="cancel-photo-read" ${photoState.busy?'':'hidden'}>Cancel reading</button></div>`:''}<p id="photo-status" role="status">${esc(photoState.status)}</p>${photoState.text?`<label class="field-label" for="photo-words">Check the words against the photo · one per line</label><textarea id="photo-words" rows="9" spellcheck="false">${esc(photoState.text)}</textarea><button class="secondary" id="use-photo-words">Use these checked spellings →</button><p class="hint">This fills the spelling editor. Your child’s list is only changed when you save or hand over.</p>`:''}</details>`;}
function cancelPhotoReader(){photoController?.abort();photoController=null;photoState.busy=false;}
function renderPhotoPanel(){const panel=$('.photo-import');if(panel){panel.outerHTML=photoReaderMarkup();bindPhotoReader();}}
function bindPhotoReader(){if(photoState.canvas&&$('#photo-crop-stage'))bindPhotoCrop($('#photo-crop-stage'),photoState.crop||suggestPhotoCrop(photoState.canvas),crop=>{photoState.crop=crop;photoState.text='';});const picker=$('#homework-photo');if(!picker)return;picker.onchange=async event=>{cancelPhotoReader();const file=event.target.files[0];if(!file)return;const profile=p();try{const canvas=await photoCanvas(file);if(view!=='parents'||!parentOpen||p()!==profile)return;photoState={file,turns:0,canvas,crop:suggestPhotoCrop(canvas),text:'',status:'Check the box covers only your spelling sheet. Drag its corner to resize.',busy:false};renderPhotoPanel();}catch(error){$('#photo-status').textContent=error.message;}};if($('#photo-upload'))$('#photo-upload').onchange=picker.onchange;$('#rotate-photo')?.addEventListener('click',async()=>{photoState.turns++;photoState.canvas=await photoCanvas(photoState.file,photoState.turns);photoState.crop=suggestPhotoCrop(photoState.canvas);photoState.text='';renderPhotoPanel();});$('#read-photo')?.addEventListener('click',async()=>{if(photoState.busy)return;photoState.busy=true;photoState.status='Getting the photo reader ready…';const controller=new AbortController(),profile=p();photoController=controller;renderPhotoPanel();try{const result=await readSpellingPhoto(cropPhoto(photoState.canvas,photoState.crop),{signal:controller.signal,onProgress:message=>{photoState.status=message;if($('#photo-status'))$('#photo-status').textContent=message;}});if(controller.signal.aborted||view!=='parents'||!parentOpen||p()!==profile)return;const unclear=result.confidence<45||result.tooMany||!result.words.length;photoState.text=unclear?'':result.words.join('\n');photoState.status=unclear?'I could not read a clear spelling list. Tighten the box around the paper, leave out the heading and try again. You can also type the words.':result.words.length+' spellings found. Check each word against the photo before using it.'+(result.reviewHints?.length?' Please check: '+result.reviewHints.map(h=>h.word+(h.suggestion?' (perhaps '+h.suggestion+')':'')).join(', ')+'.':'');}catch(error){if(!controller.signal.aborted)photoState.status='Photo reading could not finish. Try a clearer photo or type your words. '+error.message;}finally{if(photoController===controller)photoController=null;photoState.busy=false;if(view==='parents'&&parentOpen&&p()===profile)renderPhotoPanel();}});$('#cancel-photo-read')?.addEventListener('click',()=>{cancelPhotoReader();photoState.status='Photo reading stopped. You can try again.';renderPhotoPanel();});$('#photo-words')?.addEventListener('input',event=>photoState.text=event.target.value);$('#use-photo-words')?.addEventListener('click',()=>{try{const words=parseWeeklyWords($('#photo-words').value);if(!words.length)throw Error('Add at least one spelling.');$('#words').value=words.join('\n');$('#words').dispatchEvent(new Event('input',{bubbles:true}));$('#photo-status').textContent='Checked words are in the editor. Save the list when you are happy.';landAt($('#words'),{offset:55});}catch(error){$('#photo-status').textContent=error.message;}});}

function bindParents(){if(!parentOpen){const unlock=()=>{if($('#gate').value.trim()==='12'){parentOpen=true;parentMessage='';render();}else{parentMessage='Try that square root again.';render();}};$('#unlock').onclick=unlock;$('#gate').onkeydown=e=>{if(e.key==='Enter')unlock();};return;}$('#save-profile').onclick=()=>{p().name=$('#child-name').value.trim()||'My spellings';p().age=Number($('#child-age').value);p().support=$('#support').value;save();notify('Profile saved.');render();};const saveWeek=async (newWeek,handoff=false)=>{const active=p();let words;try{words=parseWeeklyWords($('#words').value);}catch(error){$('#save-feedback').textContent=error.message;return;}const date=$('#test-date').value;if(!words.length){$('#save-feedback').textContent='Add at least one spelling first.';return;}if(!date){$('#save-feedback').textContent='Choose the school spelling-test date.';return;}if(!saveEditor())return;$('#save-week').disabled=true;$('#new-week').disabled=true;$('#save-feedback').textContent='Preparing the offline word list…';const suggestions=await suggestWordList(words,[...active.words,...(active.archivedLists||[]).flatMap(a=>a.words)]);try{setWeek(active,suggestions,date,{newWeek});save();if(view==='parents'&&active===p()){selectedWord=null;if(handoff){const missing=meaningSummary(active.words);if(missing.missingMeanings.length||missing.missingSentences.length){render();$('#handoff-feedback').textContent='The list is saved. Please finish the missing meanings and example sentences above before handing over.';return;}parentOpen=false;go(active.week?.started&&!setupStatus(active).ready?'pal':'home');return;}render();notify(definitionSaveMessage(active.words));}}catch(error){if($('#save-feedback'))$('#save-feedback').textContent=error.message;if($('#save-week'))$('#save-week').disabled=false;if($('#new-week'))$('#new-week').disabled=false;}};$('#save-week').onclick=()=>saveWeek(false);$('#hand-to-child').onclick=()=>saveWeek(false,true);$('#new-week').onclick=()=>{let words;try{words=parseWeeklyWords($('#words').value);if(!words.length)throw Error('Add at least one spelling first.');if(!$('#test-date').value)throw Error('Choose the school spelling-test date.');}catch(error){$('#save-feedback').textContent=error.message;return;}confirmNewSpellingWeek({name:p().name,count:words.length,onConfirm:()=>saveWeek(true)});};$('#save-meanings').onclick=()=>{if(!saveEditor())return;save();notify('Meanings and example sentences saved.');render();};$('#spoken-questions').onchange=e=>{state.spokenQuestions=e.target.checked;save();};$('#preview-voice').onclick=()=>speak(VOICE_HELLO);bindPhotoReader();bindTeachingReview();}

function bindCommon(){ $('#baseline-test')?.addEventListener('click',startTest);$('#skip-baseline')?.addEventListener('click',()=>{p().week.baselineDismissed=true;save();render();landAt($('.how-practice')||$('.weekly-dashboard'));});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=e=>{e.preventDefault();go(b.dataset.go);});$('#profile')?.addEventListener('change',e=>{cancelSpeech();specialSuitDraft=null;state.active=e.target.value;selectedWord=null;session=null;test=null;demoBaby=null;chosenBaby=null;denGame=null;view=view==='parents'?'parents':view==='week-preview'?'week-preview':'home';save();render();});$('#sound').onclick=()=>{if(state.sound)cancelSpeech();state.sound=!state.sound;save();render();};document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>startMode(b.dataset.method));document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{selectedWord=selectedWord===b.dataset.word?null:b.dataset.word;render();});document.querySelectorAll('[data-hear]').forEach(b=>b.onclick=()=>speak(wordSpeech(b.dataset.hear)));$('#hear-all')?.addEventListener('click',toggleHearList);$('#save-pal-name')?.addEventListener('click',()=>{if(badgeCount(p())<1||p().week.design.locks.palName)return;const name=$('#pal-name').value.trim();if(!name||name==='My pal'){palNotice('What shall I be called? Type my name, then tap Confirm name.');$('#pal-name').focus();return;}p().palName=name;p().week.design.locks.palName=true;rememberLook(p());save();render();});document.querySelectorAll('[data-shape]').forEach(b=>b.onclick=()=>{if(chooseIdentity(p(),'species',b.dataset.shape)){save();render();}else notify('That shape is fixed for this spelling set.');});document.querySelectorAll('[data-colour]').forEach(b=>b.onclick=()=>{if(chooseIdentity(p(),'colour',b.dataset.colour)){save();render();}else notify('Earn the badge, then choose one colour for this spelling set.');});document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{if(chooseClothes(p(),b.dataset.category,b.dataset.claim)){save();soundEffect('celebrate');render();notify('Your choice is yours to keep!');}});document.querySelectorAll('[data-wear]').forEach(b=>b.onclick=()=>{if(equip(p(),b.dataset.category,b.dataset.wear==='none'?null:b.dataset.wear)){save();render();}});document.querySelectorAll('[data-hatch]').forEach(b=>b.onclick=()=>beginHatch(b.dataset.hatch));document.querySelectorAll('[data-baby]').forEach(b=>b.onclick=()=>{demoBaby=null;chosenBaby=b.dataset.baby;render();landAt($('.baby-collection'));});$('#start-test')?.addEventListener('click',startTest);}


function methodArt(key){const shapes={study:'<rect x="14" y="19" width="54" height="47" rx="9"/><path d="M22 34h28M22 43h21M48 23l15 40"/>',listen:'<path d="M18 46v-9a23 23 0 0146 0v9M18 38h8v22h-8zM56 38h8v22h-8zM34 35v20l17-10z"/>',build:'<rect x="9" y="16" width="26" height="28" rx="6"/><rect x="42" y="23" width="26" height="28" rx="6"/><rect x="25" y="49" width="26" height="25" rx="6"/><path d="M20 24v12M48 34h13M33 60h9"/>',letters:'<path d="M16 55l10-28 10 28M20 45h12M45 52h11M65 30v25M60 42h10"/><circle cx="51" cy="30" r="5"/>',gap:'<path d="M12 24h54M12 39h20M12 55h54"/><rect x="40" y="32" width="28" height="14" rx="4"/>',meaning:'<path d="M12 17h47v35H38L23 66V52H12zM37 27c14-7 18 7 7 11v5M43 48h1"/>',sentence:'<path d="M15 61l6-19 33-29 13 13-33 29zM21 42l13 13M15 61l19-6M48 19l13 13"/>',draw:'<path d="M25 51l25-34 14 10-25 34zM25 51c-21 2-7 20-15 19 16 4 24-1 29-9M49 21l13 9"/><circle cx="19" cy="23" r="7"/>'};return `<svg viewBox="0 0 80 80" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round">${shapes[key]}</svg>`;}
function schoolResultsPanel(){const pr=p();return `<section class="settings-card school-records"><span class="eyebrow">THE REAL SCHOOL TEST</span><h2>How did the school test go?</h2><p>Record the result for this week’s list. Tick words that need another go. Leave every box clear for full marks.</p><label class="field-label">Actual test date<input type="date" id="actual-date" value="${pr.week?.testDate||localDay()}"></label><fieldset><legend>Words that were wrong</legend><div class="wrong-word-grid">${pr.words.map(w=>`<label><input type="checkbox" data-wrong-word="${esc(w.word)}"> ${esc(w.word)}</label>`).join('')}</div></fieldset><label class="field-label">Notes (optional)<textarea id="actual-notes" maxlength="500" rows="2"></textarea></label><button class="primary" id="save-actual">Save school test result</button><p id="actual-feedback" class="feedback" role="status"></p><div class="school-history">${(pr.schoolResults||[]).map(r=>`<article><strong>${formatDay(r.date)} · ${r.score}/${r.total}</strong><p>${r.wrongWords.length?'Practise again: '+r.wrongWords.map(esc).join(', '):'All words correct!'}</p>${r.notes?`<p>${esc(r.notes)}</p>`:''}</article>`).join('')||'<p>Your school test records will stay here across spelling weeks.</p>'}</div></section>`;}
function beginHatch(id,demo=false){syncEgg(p());const egg=demo?{parent:lookOf(p()),words:structuredClone(p().words)}:p().eggs.find(e=>e.id===id);if(!demo&&(!egg||egg.hatched||!eggProgress(egg).ready))return;cancelSpeech();clearTimeout(hatchTimer);hatchTimer=null;hatchScene={id,demo,shellColour:egg.shellColour||p().eggs.at(-1)?.shellColour,taps:0,phase:'crack',token:newId(),parent:structuredClone(egg.parent),look:inheritedBaby(egg),name:'Little '+egg.parent.palName};view='hatching';pendingQuestion='A tiny wiggle! Tap the egg gently to help our baby hatch.';render();scrollTo({top:0,behavior:'smooth'});}

function hatchingPage(){return crackScenePage();}

function bindV5(){$('[data-teach-baby]')?.addEventListener('click',()=>{const b=demoBaby||p().babies.find(x=>x.id===chosenBaby)||p().babies.at(-1);if(!b)return;startMode('listen');session.nurseryBaby=b.id;render();});document.querySelectorAll('[data-eyes]').forEach(b=>b.onclick=()=>{p().eyeColour=b.dataset.eyes;save();render();});for(const id of ['demo-hatch','demo-hatch-empty','egg-preview-side'])$('#'+id)?.addEventListener('click',()=>beginHatch(null,true));$('#close-demo')?.addEventListener('click',()=>{demoBaby=null;render();});document.querySelectorAll('[data-care]').forEach(b=>b.onclick=()=>{const baby=demoBaby||p().babies.find(x=>x.id===chosenBaby)||p().babies.at(-1);if(!baby||!careForBaby(baby,b.dataset.care))return;if(!demoBaby)save();render();const status=$('.care-status');if(status)status.textContent={feed:'Nom nom! A lovely berry. Happy little tummy.',cuddle:'A warm snuggle. You are a lovely little friend.',cot:baby.care.asleep?'Tucked into the cot. Zzz…':'Good morning, little one!'}[b.dataset.care];if(b.dataset.care==='cuddle')$('.baby-display [data-pal-action=purr]')?.click();if(b.dataset.care==='feed'){const snack=document.createElement('span');snack.className='care-snack';snack.textContent='🍓';snack.setAttribute('aria-hidden','true');$('.baby-display .pal-stage')?.append(snack);$('.baby-display [data-pal-action=giggle]')?.click();}});$('#save-actual')?.addEventListener('click',()=>{try{const r=recordSchoolTest(p(),{date:$('#actual-date').value,wrongWords:[...document.querySelectorAll('[data-wrong-word]:checked')].map(el=>el.dataset.wrongWord),notes:$('#actual-notes').value});save();render();$('#actual-feedback').textContent='Saved: '+r.score+' of '+r.total+'.';}catch(e){$('#actual-feedback').textContent=e.message;}});$('#restore-list')?.addEventListener('click',()=>{$('#words').value=p().archivedLists.at(-1).words.map(w=>w.word).join('\n');notify('Previous words loaded into the editor. Save the list when you’re ready.');});}
function bindDrawing(canvas){const ctx=canvas.getContext('2d');let pen='#70579b',tool='pen',size=8,history=[],future=[];const snapshot=()=>({image:ctx.getImageData(0,0,canvas.width,canvas.height),dirty:canvasDirty});const remember=()=>{history.push(snapshot());if(history.length>20)history.shift();future=[];buttons();};const buttons=()=>{$('#undo-draw').disabled=!history.length;$('#redo-draw').disabled=!future.length;};const restore=data=>{ctx.putImageData(data.image,0,0);canvasDirty=data.dirty;};const point=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.x)/r.width*canvas.width,y:(e.clientY-r.y)/r.height*canvas.height};};const brush=()=>{ctx.globalCompositeOperation=tool==='eraser'?'destination-out':'source-over';ctx.globalAlpha=tool==='highlight'?.28:1;ctx.strokeStyle=pen;ctx.fillStyle=pen;ctx.lineWidth=tool==='brush'?size*2:tool==='eraser'?size*3:tool==='highlight'?size*3:size;ctx.lineCap='round';ctx.lineJoin='round';};canvas.onpointerdown=e=>{e.preventDefault();remember();canvas.setPointerCapture(e.pointerId);const q=point(e);canvasDirty=true;brush();if(['star','heart'].includes(tool)){ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;ctx.font=(size*4+24)+'px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(tool==='star'?'★':'♥',q.x,q.y);return;}drawing=true;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(q.x+.1,q.y+.1);ctx.stroke();};canvas.onpointermove=e=>{if(!drawing)return;const q=point(e);ctx.lineTo(q.x,q.y);ctx.stroke();};canvas.onpointerup=canvas.onpointercancel=()=>{drawing=false;ctx.globalAlpha=1;};document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;document.querySelectorAll('[data-tool]').forEach(el=>{el.classList.toggle('chosen',el===b);el.setAttribute('aria-pressed',el===b);});});document.querySelectorAll('[data-pen]').forEach(b=>b.onclick=()=>{pen=b.dataset.pen;document.querySelectorAll('[data-pen]').forEach(el=>el.classList.toggle('chosen',el===b));});$('#brush-size').oninput=e=>size=+e.target.value;$('#undo-draw').onclick=()=>{if(!history.length)return;future.push(snapshot());restore(history.pop());buttons();};$('#redo-draw').onclick=()=>{if(!future.length)return;history.push(snapshot());restore(future.pop());buttons();};$('#clear-canvas').onclick=()=>{remember();ctx.clearRect(0,0,canvas.width,canvas.height);canvasDirty=false;};buttons();}


function dailyDenCard(){const gate=denAccess(p(),localDay());return `<section class="daily-den-card"><span aria-hidden="true">${gate.open?'✧':'⌂'}</span><div><h3>${gate.open?'Your Secret Den is open!':'Your whole-list test holds the key.'}</h3><p>${gate.open?'You earned '+gate.count+'/'+gate.total+'. Play any day for this spelling set.':'Get at least '+gate.required+' of '+gate.total+' spellings right in one whole-list practice test. Up to three mistakes is fine.'}</p></div><button class="secondary" ${gate.open?'data-go="den"':'id="den-start-test"'}>${gate.open?'Enter my den →':'Try the whole list →'}</button></section>`;}
function identityPage(){return creationPage();}

function nurseryPage(){
 const pr=p(),egg=pr.eggs.find(e=>e.id===pr.week?.eggId),ep=egg?eggProgress(egg):{stage:0,ready:false},baby=demoBaby||pr.babies.find(b=>b.id===chosenBaby)||pr.babies.at(-1),look=baby&&(baby.look||BABIES.find(b=>b.id===baby.babyId));
 return `<section class="page-intro"><div><span class="eyebrow">YOUR GROWING LITTLE SPELLING FAMILY</span><h1>Your little crèche.</h1><p>Every baby you’ve collected lives here. Choose a little one to feed, cuddle and tuck in.</p></div></section>
 <div class="nursery-overview"><section class="creche-room nursery-room" aria-label="All your collected baby Spelloids">${nurseryWallMarkup()}<div class="creche-room-heading"><span class="creche-mobile" aria-hidden="true">☾ ✧</span><h2>${pr.babies.length} little ${pr.babies.length===1?'Spelloid':'Spelloids'}</h2><p>A cosy place for everyone.</p></div><div class="creche-babies">${pr.babies.map(b=>{const l={...(b.look||BABIES.find(spec=>spec.id===b.babyId)||{species:'bobble',colour:'grey'}),baby:true,babyOutfit:b.care?.outfit||'none'};return `<button class="creche-baby ${b.id===baby?.id?'selected':''}" data-baby="${esc(b.id)}" aria-pressed="${b.id===baby?.id}" aria-label="Care for ${esc(b.name)}"><span class="creche-pillow"><img data-baby-portrait="${esc(JSON.stringify(l))}" alt="${esc(b.name)}, your baby ${esc(l.species)}"><span class="baby-mood">${b.care?.asleep?'Zzz…':b.care?.teddy?'♥ Teddy time':'Hello!'}</span></span><strong>${esc(b.name)}</strong><small>${b.care?.asleep?'Cosy and asleep':'Ready for a cuddle'}</small></button>`;}).join('')||'<div class="creche-empty"><span aria-hidden="true">✧</span><h3>A little room for your first baby.</h3><p>Make every word green to hatch your egg.</p></div>'}</div></section>
 <aside class="nursery-egg-companion" aria-label="Your spelling egg"><span class="eyebrow">YOUR LITTLE SPELLING EGG</span>${egg?`<h2>${egg.hatched?'A little one hatched!':ep.ready?'Ready to meet you!':'Growing with your words'}</h2><button class="hub-return" data-go="home">← Back to Spelling Hub</button><div class="egg-stage">${eggSVG(egg)}</div><strong class="egg-word-count">${ep.green} / ${ep.wordCount} words green</strong><progress class="egg-mastery-progress" value="${ep.steps||0}" max="${ep.total||1}" aria-label="Completed spelling challenges"></progress><p class="egg-progress-detail">${ep.steps||0} / ${ep.total||0} challenge lights · ${Math.round((ep.steps||0)/Math.max(1,ep.total||0)*100)}%</p><p>${egg.hatched?'Your baby is playing in the nursery. Your family picture is on the wall.':ep.ready?'Every word is green. Tap below to help your baby hatch.':'Each green word adds a little more cracking.'}</p>${!egg.hatched&&ep.ready?`<button class="primary" data-hatch="${egg.id}">Help our baby hatch →</button>`:''}`:'<p>A new spelling set brings a new egg.</p>'}<button class="text-button" id="demo-hatch">Try a hatch preview</button></aside></div>
 ${pr.eggs.filter(e=>e.id!==egg?.id&&!e.hatched&&eggProgress(e).ready).map(e=>`<button class="secondary" data-hatch="${e.id}">Hatch a completed spelling set →</button>`).join('')}
 <section class="baby-collection">${baby&&look?`<div class="section-heading"><div><h2>Time with ${esc(baby.name)}</h2><p>Drag strawberries and little things onto your baby to play.</p></div></div><div class="baby-layout"><div class="baby-display ${baby.care?.asleep?'sleeping':''}" data-baby-play><h3>${esc(baby.name)}${demoBaby?' · preview':''}</h3><div class="baby-feed-scene">${palMarkup({...look,palName:baby.name,asleep:baby.care?.asleep,babyOutfit:baby.care?.outfit||'none'},{baby:true})}<div class="baby-cot" data-cot ${baby.care?.asleep?'':'hidden'}>${cotMarkup()}</div><div class="berry-tray strawberry-tray"><div class="strawberries">${['a','b','c'].map(berryMarkup).join('')}</div><p data-berry-count>${snackBerries(baby).length} strawberries left</p><button class="small-button" data-refill-berries ${snackBerries(baby).length?'hidden':''}>Three more strawberries</button><p>Pick up, slide, munch!</p></div></div><p class="care-status" role="status">${baby.care?.asleep?'Sleeping soundly. Zzz…':'A little snack and a gentle rock?'}</p><div class="baby-care"><button class="secondary" data-care="cuddle">♥ Cuddle</button><button class="secondary" data-care="cot">${baby.care?.asleep?'☀ Wake up':'☾ Into the cot'}</button><button class="secondary" data-teach-baby>♫ Teach a weekly word</button></div><label class="field-label" for="baby-name">My baby’s name</label><div class="inline-input baby-name-input"><input id="baby-name" maxlength="24" value="${esc(baby.name)}"><button class="small-button" id="save-baby-name">Save</button></div>${demoBaby?'<button class="text-button" id="close-demo">Close preview</button>':''}</div>${nurseryToolbox(baby)}</div>`:'<div class="empty-collection"><h3>Meet your first baby soon.</h3><p>Complete every word’s six challenges, then tap your egg to hatch it.</p><button class="secondary" id="demo-hatch-empty">Try a hatch preview →</button></div>'}</section>`;
}

function crackScenePage(){const h=hatchScene;if(!h)return nurseryPage();const reveal=h.phase==='reveal',rumble=h.phase==='rumble';return `<section class="hatch-scene hatch-${h.phase}"><span class="eyebrow">${h.demo?'PREVIEW · REAL PROGRESS STAYS AS IT IS':'EVERY SPELLING COMPLETE'}</span><h1>${reveal?'Hello, '+esc(h.name)+'!':rumble?'A little rumble…':'Tap, tap… who’s inside?'}</h1><div class="hatch-stage ${reveal?'revealed':''}" ${!reveal&&!rumble?'data-crack role="button" tabindex="0" aria-label="Tap the egg to crack it"':''}>${reveal?`<div class="broken-shell" aria-hidden="true"><i></i><i></i></div><div class="hatch-confetti" aria-hidden="true">✦ ✧ ♥ ✦</div>${palMarkup({...h.look,palName:h.name},{baby:true})}`:eggSVG({shellColour:h.shellColour,steps:h.taps,total:4,green:h.taps,wordCount:4})}</div><p>${reveal?'A little version of your very own '+esc(h.parent.palName)+'. Time for a cuddle.':rumble?'Stand back. A little friend is coming!':h.taps+' of 4 gentle taps. Tap anywhere on the egg to make another crack.'}</p>${!reveal&&!rumble?'<p class="hint">Your baby inherits this monster’s look. <button class="text-button" data-go="pal">Finish my monster first</button></p>':''}${reveal?'<button class="primary" id="meet-baby">Take us to the nursery →</button>':!rumble?'<button class="secondary" data-crack>Tap the egg ✧</button>':''}<button class="text-button" data-go="egg">${h.demo?'Close preview':'Back to the nursery'}</button></section>`;}
function denPage(){const pr=p(),gate=denAccess(pr,localDay());return `<section class="page-intro"><div><span class="eyebrow">SPELLING MILESTONES. NEW PLACES TO PLAY.</span><h1>Your Secret Den.</h1><p>Finish whole challenge modules to open your games.</p></div><button class="secondary" data-go="home">← Spelling Hub</button></section><section class="den-progress-strip"><strong>${gate.completedModules.length} / 6 modules complete</strong><p>${gate.open?'Your Den is open. Keep spelling to discover more games.':'One complete module opens Word Rocket and Cloud Hopper.'}</p></section><section class="secret-den-v12" aria-label="Your unlocked games and future rewards">${denGallery(pr)}</section>`;}

function denPlayPage(){if(['pairs','bingo'].includes(denGame?.engine)&&denAccess(p(),localDay()).open)return tableGamePage();if(denGame?.engine==='wordsearch'&&denAccess(p(),localDay()).open)return wordsearchPage();if(!denGame||!denAccess(p(),localDay()).open)return denPage();return `<div class="activity-header"><button class="text-button" data-go="den">← My secret den</button><strong>${esc(denGame.name)}</strong><button class="secondary" id="pause-den">Ⅱ Pause</button></div><div class="den-score"><strong>Words <span id="den-collected">0 / ${p().words.length}</span></strong><span id="den-hearts" aria-label="Three chances">♥♥♥</span></div><section class="den-play-area engine-${denGame.engine}"><canvas id="den-canvas" tabindex="0" aria-label="${denGame.engine==='rocket'?'Steer up and down to collect word capsules. Use touch, mouse or arrow keys.':'Steer left and right to land on word clouds. Use touch, mouse or arrow keys.'}"></canvas><div class="den-rider" aria-hidden="true">${palMarkup(p())}</div><div class="den-finish" id="den-finish" hidden><h2 id="den-finish-title"></h2><p id="den-finish-score"></p><button class="primary" id="replay-den">New course. Play again →</button><button class="secondary" data-go="den">Back to my den</button></div></section><p class="den-help" id="den-status" role="status">${denGame.engine==='rocket'?'Drag up and down, or use ↑ ↓. Fly through the word capsules. Avoid the asteroids.':'Drag left and right, or use ← →. Bounce onto each word cloud. The first jump starts for you.'}</p><p class="den-collected-words" id="den-word-list"></p>`;}
function portraitArt(frame){return frame.image?`<img class="family-picture" src="${frame.image}" alt="${esc(frame.adult.palName)} embracing ${esc(frame.baby.palName)}">`:familyPicture(frame.adult,frame.baby);}
function nurseryWallMarkup(){const pr=p(),frame=pr.portraits.find(f=>f.id===chosenPortrait);return `<div class="nursery-wall-heading"><h2>Our family pictures</h2><p>Tap a frame for its spellings, keepsakes and learning story.</p></div><section class="family-wall">${pr.portraits.length||pr.archivedCycles?.some(c=>c.scrapbook?.length&&!pr.portraits.some(f=>f.weekId===c.week.id))?pr.portraits.map((f,i)=>`<button class="family-frame frame-${i%3}" data-portrait="${f.id}">${portraitArt(f)}<strong>${esc(f.adult.palName)} & ${esc(f.baby.palName)}</strong><small>${f.words.length} words · all six challenges complete</small><span class="portrait-seal">✧</span></button>`).join('')+archivedSetCovers(pr):'<div class="empty-frame"><span>♥</span><h2>Your first family picture will hang here.</h2><p>Finish every word’s six challenges, hatch your baby and keep that spelling set’s monster forever in a portrait.</p><button class="secondary" id="demo-family">Preview a family picture</button></div>'}</section>${frame?`<dialog id="portrait-detail"><button class="small-button dialog-close" id="close-portrait">Close ✕</button>${portraitArt(frame)}<h2>${esc(frame.adult.palName)} & ${esc(frame.baby.palName)}</h2><p>Hatched ${formatDay(frame.date)} · all ${frame.words.length*6} challenges complete</p><div class="portrait-word-list">${frame.words.map(w=>`<span>${esc(w.word)}</span>`).join('')}</div>${portraitStats(frame)}${familyScrapbookMarkup(frame.weekId)}${pr.schoolResults.filter(r=>r.weekId===frame.weekId).map(r=>`<p class="portrait-result">School test: ${r.score}/${r.total}${r.wrongWords.length?' · Practise again: '+r.wrongWords.map(esc).join(', '):' · Full marks!'}</p>`).join('')||'<p class="hint">A grown-up can add the real school test result in settings.</p>'}</dialog>`:''}`;}
function fitWords(){const measure=document.createElement('canvas').getContext('2d');const fit=()=>document.querySelectorAll('.word-chip>strong').forEach(label=>{label.style.fontSize='';const chip=label.parentElement,style=getComputedStyle(chip),small=chip.querySelector('small'),count=chip.querySelector('.word-count');const available=chip.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight)-(small?.offsetWidth||0)-(count?.offsetWidth||0)-parseFloat(style.gap)*2;let size=parseFloat(getComputedStyle(label).fontSize);const width=()=>{measure.font=getComputedStyle(label).font;return measure.measureText(label.textContent).width;};while(width()>available&&size>(chip.closest('.weekly-dashboard')?12:17)){size-=.5;label.style.fontSize=size+'px';}});const observer=new ResizeObserver(fit);document.querySelectorAll('.word-grid,.method-grid,.page-intro').forEach(el=>observer.observe(el));requestAnimationFrame(fit);return()=>observer.disconnect();}

function bindV6(){document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{state.theme=b.dataset.themeChoice;save();go('home');});document.querySelectorAll('[data-antennae]').forEach(b=>b.onclick=()=>{if(chooseIdentity(p(),'antennae',b.dataset.antennae)){save();render();}});$('#toggle-freckles')?.addEventListener('click',()=>{if(canFreckle(p())){p().freckles=!p().freckles;rememberLook(p());save();render();}});document.querySelectorAll('[data-den-game]').forEach(b=>b.onclick=()=>{if(!denAccess(p(),localDay()).open){notify('Finish any one of your six challenge modules to open the Den.');return;}denGame=p().denLibrary.find(g=>g.id===b.dataset.denGame);cancelSpeech();view='play';render();$('.den-play-area')?.scrollIntoView({block:'center',behavior:'instant'});});$('#replay-den')?.addEventListener('click',()=>render());if(view==='play'&&$('#den-canvas')){const weekId=p().week.id;cleanDen=mountDenGame({game:denGame,words:p().words,access:()=>p().week.id===weekId&&denAccess(p(),localDay()).open,onWord:word=>{if(state.sound)speak(wordSpeech(word),{quiet:true});},onFinish:result=>{(p().denHistory??=[]).unshift({...result,gameId:denGame.id,weekId,day:localDay()});p().denHistory=p().denHistory.slice(0,40);save();},onLocked:()=>{go('den');notify('Finish a challenge module for this spelling set to open the Den.');}});}document.querySelectorAll('[data-portrait]').forEach(b=>b.onclick=()=>{chosenPortrait=b.dataset.portrait;render();});const dialog=$('#portrait-detail');if(dialog){dialog.showModal();dialog.addEventListener('cancel',()=>chosenPortrait=null);$('#close-portrait').onclick=()=>{chosenPortrait=null;render();};}$('#demo-family')?.addEventListener('click',()=>{const look=lookOf(p());const dialog=document.createElement('dialog');dialog.className='portrait-preview';dialog.innerHTML='<button class="small-button" id="close-family-demo">Close preview ✕</button>'+familyPicture(look,{...look,palName:'Little '+look.palName,wearing:{}})+'<h2>'+esc(look.palName)+' & Little '+esc(look.palName)+'</h2><p>Preview only. Complete this spelling set to earn your own picture.</p>';document.body.append(dialog);dialog.showModal();dialog.querySelector('button').onclick=()=>dialog.remove();dialog.oncancel=()=>dialog.remove();});if(view==='egg'){const baby=demoBaby||p().babies.find(b=>b.id===chosenBaby)||p().babies.at(-1);if(baby&&$('[data-baby-play]')){const creature=$('[data-baby-play] [data-pal]');creature.setAttribute('aria-label','Tap '+baby.name+' gently five times to rock them to sleep.');const mouth=document.createElement('span');mouth.dataset.mouthTarget='';mouth.className='mouth-target';mouth.setAttribute('aria-hidden','true');creature.append(mouth);const playCleanup=bindBabyPlay({baby,onSave:()=>{if(!demoBaby)save();},onStatus:text=>{$('.care-status').textContent=text;},onMunch:()=>{if(state.sound)soundEffect('munch');}});const careCleanup=bindNurseryCare({baby,onSave:()=>{if(!demoBaby)save();},onStatus:text=>{$('.care-status').textContent=text;},onRefresh:render,onBurp:()=>{if(state.sound)soundEffect('burp');}});cleanBaby=()=>{playCleanup();careCleanup();};$('#save-baby-name').onclick=()=>{baby.name=$('#baby-name').value.trim()||'Little friend';if(!demoBaby){p().portraits.filter(f=>f.babyId===baby.id).forEach(f=>f.baby.palName=baby.name);save();}render();};}}if(view==='hatching'&&hatchScene){const h=hatchScene;const crack=()=>{if(h!==hatchScene||h.phase!=='crack')return;h.taps++;soundEffect('oof');if(h.taps===4){h.phase='rumble';render();hatchTimer=setTimeout(()=>{hatchTimer=null;if(h!==hatchScene)return;h.phase='reveal';if(h.demo)demoBaby={id:'preview-only',name:h.name,look:h.look,care:{feeds:0,cuddles:0,asleep:false,rocks:0}};else if(hatchEgg(p(),h.id)){chosenBaby=p().babies.at(-1).id;const frame=p().portraits.find(f=>f.babyId===chosenBaby);if(frame){try{frame.image=renderFamilyPortrait(frame.adult,frame.baby);}catch{}}save();}render();soundEffect('celebrate');},850);}else render();};cleanHatch=bindHatchTap(document.querySelectorAll('[data-crack]'),crack);$('#meet-baby')?.addEventListener('click',()=>{hatchScene=null;view='egg';render();$('.baby-feed-scene')?.scrollIntoView({behavior:'smooth',block:'center'});});}}

function advancePractice(skipped=false){if(!session||session.finished)return;skipped=skipped||!!session.retryExhausted;cancelSpeech();const word=session.items[session.index];let result={credited:false};if(!skipped)result=completeWord(p(),word.word,session.method);save();session.index++;if(session.index>=session.items.length){session.finished=true;session.credited=result.credited;pendingQuestion=null;if(state.sound)soundEffect('celebrate');}else{Object.assign(session,{answer:'',answered:false,revealed:false,feedback:'',covered:false,built:[],letters:[],choices:null,mistakes:0,retryExhausted:false});pendingQuestion=questionText();}render();}
function captureUnlock(before){const after=badgeCount(p());if(after>before){unlockOffer={badges:badgesFor(p()).slice(before,after),profileId:p().id,weekId:p().week.id};pendingQuestion=null;}}
function acknowledgeUnlock(){if(!unlockOffer)return;p().week.announcedBadges=[...new Set([...(p().week.announcedBadges||[]),...unlockOffer.badges.map(b=>b.id)])];unlockOffer=null;save();}
function openCustomiser(){cancelSpeech();acknowledgeUnlock();if(['game','test'].includes(view))pausedPractice={view,session,test,profileId:p().id,weekId:p().week.id};pendingQuestion=null;view='pal';render();scrollTo({top:0,behavior:'smooth'});}
function resumePractice(){cancelSpeech();if(!pausedPractice||pausedPractice.profileId!==p().id||pausedPractice.weekId!==p().week.id){pausedPractice=null;go('home');return;}const resume=pausedPractice;pausedPractice=null;view=resume.view;session=resume.session;test=resume.test;if(view==='game'&&session?.answered&&!session.finished){advancePractice();return;}pendingQuestion=questionText();render();}
function availableCreation(){const pr=p(),level=badgeCount(pr),locks=pr.week?.design?.locks||{};return[level>=1&&!locks.species?'shape':null,level>=1&&pr.species!=='blob'&&!pr.voiceStyle?'voice':null,level>=2&&!locks.colour?'colour':null,level>=3&&!locks.antennae?'antennae':null,finishAvailable(pr)?'freckles or earrings':null].filter(Boolean);}
function creationTools(){const available=availableCreation(),extra=view==='test'?test?.extraPractice:session?.extraPractice;return `<div class="creation-tools ${available.length?'feature-ready':''}"><div><strong>${extra?'Extra practice · no new creation rewards':weekAnswers(p())+' creation questions · '+badgeCount(p())+' badges'}</strong><small>${available.length?'Ready to choose: '+available.join(', '):'Next: Badge '+(badgeCount(p())+1)+' · '+(badgeSteps(p()).find(n=>n>weekAnswers(p()))||'all earned')+' correct challenges'}${!p().voiceStyle?' · Word guide reads until your pal has a voice.':''}</small></div><button class="${available.length?'primary':'small-button'}" data-update-pal>${available.length?'✧ New choices! Update my pal':'Update my pal'}</button></div>`;}
function unlockMarkup(){if(!unlockOffer)return'';const badge=unlockOffer.badges.at(-1);return `<dialog id="creation-unlock" aria-labelledby="unlock-title"><div class="unlock-medal" aria-hidden="true">✧<b>${badge.id}</b></div><span class="eyebrow">BADGE ${badge.id}${badge.id===1?' · READY TO LEARN':' · '+badge.at+' QUESTIONS ANSWERED'}</span><h2 id="unlock-title">${esc(badge.title)} badge!</h2><p>${esc(badge.description)}</p><div class="unlock-pal">${palMarkup(p(),{prompt:badge.description})}</div><div class="unlock-buttons"><button class="primary" id="unlock-customise">Make my pal more me →</button><button class="secondary" id="unlock-continue">Keep playing →</button></div><p class="hint">Your question and progress are saved. Come straight back after choosing.</p></dialog>`;}
let creationDraft={context:null,species:null,colour:null,antennae:null,voiceStyle:null};
function draftForWeek(){const context=p().id+':'+p().week?.id;if(creationDraft.context!==context)creationDraft={context,species:null,colour:null,antennae:null,clothes:{},finish:null};creationDraft.clothes??={};return creationDraft;}
function creationCompanion(){const pr=p(),draft=draftForWeek(),preview={...pr,...Object.fromEntries(['species','colour','antennae'].filter(k=>draft[k]).map(k=>[k,draft[k]])),freckles:draft.finish?draft.finish==='freckles':pr.freckles,wearing:{...pr.wearing,...(draft.finish==='earrings'?{earrings:WARDROBE.earrings.items[0].id}:{}),...draft.clothes}};return `<aside class="companion-card creation-companion"><div class="companion-name"><span>${['species','colour','antennae','voiceStyle','finish'].some(k=>draft[k])||Object.keys(draft.clothes||{}).length?'TRYING A LOOK · NOT CHOSEN YET':'YOUR VERY OWN LITTLE PAL'}</span><h2>${esc(pr.palName)}</h2></div>${palMarkup(preview,{prompt:setupMessage(pr)})}${setupLaunchMarkup(pr)}<p data-voice-status class="voice-status" role="status"></p>${rewardSummary()}${pausedPractice?'<button class="primary" data-resume-practice>Back to my practice →</button>':''}</aside>`;}
function creationPage(){
 const pr=p(),draft=draftForWeek(),locks=pr.week?.design?.locks||{},level=badgeCount(pr),resume=pausedPractice&&pausedPractice.profileId===pr.id&&pausedPractice.weekId===pr.week.id;
 const wardrobe=Object.entries(WARDROBE).filter(([category])=>!pr.week?.claimed?.[category]&&rewardAvailable(pr,category)).map(([category,slot])=>`<fieldset class="wardrobe-slot" data-choice-group="${category}"><legend>Badge ${{hat:4,coat:4,shoes:4,glasses:5,gloves:5,earrings:6}[category]} · ${slot.title}</legend><div class="clothing-choices">${slot.items.filter(item=>!pr.items.includes(item.id)).map(item=>`<button class="clothes-choice ${draft.clothes?.[category]===item.id?'selected':''}" data-preview-clothing="${item.id}" data-category="${category}"><span class="clothes-icon" style="--item:${item.colour}">${{hat:'♧',coat:'♢',shoes:'⌁',glasses:'◎',gloves:'✋',earrings:'✧'}[category]}</span><strong>${item.label}</strong><small>${draft.clothes?.[category]===item.id?'Trying on':'Try it on'}</small></button>`).join('')}</div>${draft.clothes?.[category]?`<button class="primary commit-choice" data-confirm-clothing="${category}">Confirm ${slot.items.find(i=>i.id===draft.clothes[category])?.label} ✓</button><button class="text-button" data-cancel-clothing="${category}">Keep looking</button>`:''}</fieldset>`).join('');
 const owned=Object.entries(WARDROBE).filter(([category,slot])=>slot.items.some(item=>pr.items.includes(item.id))&&(category!=='earrings'||['earrings','legacy-both'].includes(pr.week?.design?.finish))).map(([category,slot])=>`<fieldset><legend>${slot.title}</legend><div class="owned-items"><button class="small-button" data-wear="none" data-category="${category}">No ${category}</button>${slot.items.filter(item=>pr.items.includes(item.id)).map(item=>`<button class="small-button ${pr.wearing[category]===item.id?'wearing':''}" data-wear="${item.id}" data-category="${category}">${item.label}</button>`).join('')}</div></fieldset>`).join('');
 const badges=`<details class="badge-album"><summary>My badges · ${level} earned</summary><div class="creation-path">${badgesFor(pr).map(b=>`<div class="${level>=b.id?'earned':'mystery-badge'}"><span>✧ Badge ${b.id}</span><strong>${level>=b.id?b.title:'A surprise to discover'}</strong><small>${b.id===1?'Choose to learn':b.at+' correct challenges'}</small><p>${level>=b.id?b.description:'More ways to make your pal yours will appear here.'}</p></div>`).join('')}</div></details>`;
 const eyes=level>=2?`<fieldset><legend>Eye colour</legend><div class="colour-choices">${Object.entries(EYE_COLOURS).map(([key,c])=>`<button class="swatch ${pr.eyeColour===key?'selected':''}" style="--colour:${c}" data-eyes="${key}" aria-label="${key} eyes" ${pr.species==='blob'?'disabled':''}>${pr.eyeColour===key?'✓':''}</button>`).join('')}</div></fieldset>`:'';
 return `<section class="page-intro"><div><span class="eyebrow">BADGES BUILD YOUR VERY OWN LITTLE MONSTER</span><h1>Let’s make your Spelloid.</h1><p>Try the options, then confirm. Chosen features disappear from this screen and stay with your pal for this set.</p></div>${resume?'<button class="primary" data-resume-practice>Keep playing →</button>':''}</section>${!pr.week?.started?'<section class="pledge-card"><h2>Badge 1 · Ready to learn</h2><p>Choose to have a go. Then name your pal, choose its shape and give it a voice.</p><button class="primary" id="start-learning">I’m ready to learn! ✧</button></section>':''}<div class="pal-layout">${creationCompanion()}<section class="customise-card">
 ${level>=1&&(!locks.palName||!locks.species||!locks.voiceStyle)?`<fieldset data-choice-group="identity"><legend>Badge 1 · Name, shape & voice</legend><p class="hint">Try before confirming. These choices stay for this spelling set. Next week, make someone new!</p>
 ${!locks.palName?`<div data-choice-group="name"><label class="field-label" for="pal-name">My Spelloid’s name</label><div class="inline-input"><input id="pal-name" maxlength="24" value="${esc(pr.palName)}"><button class="secondary" id="save-pal-name">Confirm name</button></div></div>`:''}
 ${!locks.species?`<div data-choice-group="shape"><h3>Choose my shape</h3><p class="hint">Tap each shape to preview it beside you.</p><div class="shape-choices">${BODY_SHAPES.map((shape,i)=>`<button class="choice ${(draft.species||pr.species)===shape?'selected':''}" data-preview-shape="${shape}" ${identityAvailable(pr,'species',shape)?'':'disabled'}><strong>${['Bobble','Blip','Wiggle'][i]}</strong><small>${['A round little cuddle','Three curious eyes','A tall, gentle oddball'][i]}</small></button>`).join('')}</div>${draft.species?'<button class="primary commit-choice" data-commit-identity="species">Confirm shape · keep for this set ✓</button>':''}</div>`:''}
 ${!locks.voiceStyle?`<div data-choice-group="voice"><h3>Give my pal a voice</h3><p class="hint">${pr.species==='blob'?'Confirm your shape, then listen to the three voices.':'Listen, select, then confirm a voice. Every voice keeps the same natural speaking speed.'}</p><div class="voice-choices">${Object.entries(ALIEN_VOICES).map(([key,voice])=>`<article class="voice-choice ${draft.voiceStyle===key?'selected':''}"><h3>${voice.name}</h3><p>${voice.description}</p><button class="secondary" data-audition="${key}" ${pr.species!=='blob'?'':'disabled'}>♫ Listen</button><button class="small-button" data-set-voice="${key}" ${pr.species!=='blob'?'':'disabled'}>${draft.voiceStyle===key?'Selected to preview':'Select this voice'}</button></article>`).join('')}</div>${draft.voiceStyle?'<div class="voice-confirm-row"><button class="primary" id="confirm-voice">Confirm voice · keep for this set ✓</button></div>':''}<p data-voice-status class="voice-status" role="status"></p></div>`:''}</fieldset>`:''}
 ${level>=2&&!locks.colour?`<fieldset data-choice-group="colour"><legend>Badge 2 · A splash of colour</legend><p class="hint">Try the colours. Confirm one to keep until next week.</p><div class="colour-choices">${BODY_COLOURS.map(key=>`<div class="colour-option"><button class="swatch ${(draft.colour||pr.colour)===key?'selected':''}" data-preview-colour="${key}" style="--colour:${suitSwatch(key)}" aria-label="${key}" ${identityAvailable(pr,'colour',key)?'':'disabled'}>${(draft.colour||pr.colour)===key?'✓':''}</button><small>${SPECIAL_SUITS.some(s=>s.id===key)?SPECIAL_SUITS.find(s=>s.id===key).name+(specialUnlocked(pr,key)?'':' · scrapbook reward'):key}</small></div>`).join('')}</div>${draft.colour?'<button class="primary commit-choice" data-commit-identity="colour">Confirm colour · keep for this set ✓</button>':''}</fieldset>`:''}
 ${level>=3&&!locks.antennae?`<fieldset data-choice-group="antennae"><legend>Badge 3 · Hello, antennae!</legend><p class="hint">Try the options, then confirm one for this spelling set.</p><div class="shape-choices">${FEELERS.map(key=>`<button class="choice ${(draft.antennae||pr.antennae)===key?'selected':''}" data-preview-antennae="${key}" ${identityAvailable(pr,'antennae',key)?'':'disabled'}><strong>${key[0].toUpperCase()+key.slice(1)}</strong></button>`).join('')}</div>${draft.antennae?'<button class="primary commit-choice" data-commit-identity="antennae">Confirm antennae · keep for this set ✓</button>':''}</fieldset>`:''}
 ${finishAvailable(pr)?`<fieldset data-choice-group="finish"><legend>Badge 6 · The finishing touch</legend><p class="hint">Choose freckles or earrings for this set.</p><div class="shape-choices"><button class="choice" data-preview-finish="freckles">Tiny freckles</button><button class="choice" data-preview-finish="earrings">Earrings</button></div>${draft.finish?`<button class="primary commit-choice" id="confirm-finish">Confirm ${draft.finish} ✓</button>`:''}</fieldset>`:''}
 ${wardrobe}${specialRewardMarkup()}${level&&availableCreation().length===0&&!wardrobe?'<p class="choices-complete">Your choices are on your pal! Keep spelling to discover your next badge.</p>':''}${owned||eyes?`<details class="collection-drawer"><summary>My collection · clothes & eyes</summary><p class="hint">You can change these as you play. Your confirmed shape, body colour, voice and antennae stay for this set.</p>${eyes}${owned}</details>`:''}${badges}${!level?'<p>Your first choices will appear after your Ready to learn badge.</p>':''}${resume?'<button class="primary" data-resume-practice>Return to my practice →</button>':''}
 </section></div>`;
}

function studioPage(){return `<section class="page-intro"><div><span class="eyebrow">CHARACTER & VOICE REVIEW · NO PROGRESS CHANGED</span><h1>A softer little space family.</h1><p>Try the new characters and tap a voice sample. Nothing plays automatically.</p></div><button class="secondary" id="stop-voice-preview">Stop audio ■</button></section><div class="character-studio"><article class="studio-card"><span class="eyebrow">THE BEGINNING</span><h2>A little grey blob.</h2>${palMarkup({species:'blob',colour:'grey',antennae:'none',wearing:{},palName:'Little beginning'})}<p>Choose to learn to earn Badge 1 and begin its creation story.</p></article>${[['bobble','mint','sprout','bubbles'],['blip','peach','curly','mallow'],['wiggle','lilac','floppy','heart2']].map(([species,colour,antennae,voice])=>`<article class="studio-card"><span class="eyebrow">AFTER SHAPE, COLOUR & ANTENNA BADGES</span><h2>${species[0].toUpperCase()+species.slice(1)}</h2>${palMarkup({species,colour,antennae,wearing:{},palName:species,eyeColour:'violet',voiceStyle:voice})}<button class="primary" data-studio-voice="${voice}">♫ Hear ${ALIEN_VOICES[voice].name}</button><p>${ALIEN_VOICES[voice].description}</p></article>`).join('')}</div><p data-voice-status class="voice-status studio-status" role="status"></p><p class="hint">Choose Bumble, Fizzlet or Mallow. Pitch and tone can differ; speed stays the same. Listen on your tablet and choose the clearest voice for you.</p><button class="secondary" data-go="home">Back to the spelling game →</button>`;}
function bindV7(){document.querySelectorAll('[data-preview-finish]').forEach(b=>b.onclick=()=>{if(finishAvailable(p())){draftForWeek().finish=b.dataset.previewFinish;render();}});$('#confirm-finish')?.addEventListener('click',()=>{if(chooseFinish(p(),draftForWeek().finish)){draftForWeek().finish=null;save();render();}});document.querySelectorAll('[data-preview-clothing]').forEach(b=>b.onclick=()=>{if(rewardAvailable(p(),b.dataset.category)){draftForWeek().clothes[b.dataset.category]=b.dataset.previewClothing;render();}});document.querySelectorAll('[data-confirm-clothing]').forEach(b=>b.onclick=()=>{const category=b.dataset.confirmClothing,id=draftForWeek().clothes[category];if(chooseClothes(p(),category,id)){delete draftForWeek().clothes[category];save();render();notify('Your choice is yours to keep!');}});document.querySelectorAll('[data-cancel-clothing]').forEach(b=>b.onclick=()=>{delete draftForWeek().clothes[b.dataset.cancelClothing];render();});document.querySelectorAll('[data-update-pal]').forEach(b=>b.onclick=openCustomiser);document.querySelectorAll('[data-resume-practice]').forEach(b=>b.onclick=resumePractice);for(const[kind,selector]of[['species','[data-preview-shape]'],['colour','[data-preview-colour]'],['antennae','[data-preview-antennae]']])document.querySelectorAll(selector).forEach(b=>b.onclick=()=>{const value=b.dataset[kind==='species'?'previewShape':kind==='colour'?'previewColour':'previewAntennae'];if(identityAvailable(p(),kind,value)){draftForWeek()[kind]=value;render();}});document.querySelectorAll('[data-commit-identity]').forEach(b=>b.onclick=()=>{const kind=b.dataset.commitIdentity,value=draftForWeek()[kind];if(value&&chooseIdentity(p(),kind,value)){draftForWeek()[kind]=null;save();render();if(state.sound)soundEffect('celebrate');}});document.querySelectorAll('[data-audition],[data-studio-voice]').forEach(b=>b.onclick=()=>{cancelSpeech();pendingQuestion=null;guideSpeaking=false;activeVoice=b.dataset.audition||b.dataset.studioVoice;alienSpeaker.say(VOICE_HELLO,activeVoice);});$('#stop-voice-preview')?.addEventListener('click',cancelSpeech);document.querySelectorAll('[data-set-voice]').forEach(b=>b.onclick=()=>{draftForWeek().voiceStyle=b.dataset.setVoice;render();});document.querySelectorAll('[data-finish]').forEach(b=>b.onclick=()=>{if(chooseFinish(p(),b.dataset.finish)){save();render();if(state.sound)soundEffect('celebrate');}});const dialog=$('#creation-unlock');if(dialog&&unlockOffer){dialog.showModal();if(!unlockOffer.announced){unlockOffer.announced=true;if(state.sound){soundEffect('celebrate');if(p().voiceStyle){speak('A new badge! You have unlocked more ways to make me your own!',{quiet:true});}}}$('#unlock-customise').onclick=openCustomiser;const keep=()=>{cancelSpeech();acknowledgeUnlock();if(view==='game'&&session?.answered&&!session.finished)advancePractice();else{pendingQuestion=questionText();render();}};$('#unlock-continue').onclick=keep;dialog.oncancel=e=>{e.preventDefault();keep();};}}
function packsPage(){return `<section class="page-intro"><div><span class="eyebrow">NO HOMEWORK LIST? A NEW LITTLE CHALLENGE.</span><h1>Pick 20 new words.</h1><p>Choose a school-year group, shuffle a pack, then preview it together. Your current spelling set stays safe until you confirm a new one.</p></div><button class="secondary" data-go="home">Back to my words →</button></section><section class="pack-picker settings-card"><label class="field-label" for="pack-level">School-year group<select id="pack-level">${Object.entries(PACK_LEVELS).map(([key,level])=>`<option value="${key}" ${packLevel===key?'selected':''}>${level.title} · ${level.age}</option>`).join('')}</select></label><p>${PACK_LEVELS[packLevel].note}. Choose the level that suits your child’s current learning.</p><button class="primary" id="shuffle-pack">${packDraft?'Shuffle another 20':'Find my 20 words'} ✧</button><p class="hint">Based on <a href="${CURRICULUM_SOURCE}" target="_blank" rel="noopener noreferrer">England’s spelling curriculum</a>. Other UK nations use different curricula. These are practice selections, not a school-assigned list. Simple meanings and sentences are included and editable by a grown-up.</p></section>${packDraft?`<section class="settings-card pack-preview"><span class="eyebrow">PREVIEW · ${PACK_LEVELS[packLevel].title}</span><h2>Meet your next 20 words.</h2><div class="pack-words">${packDraft.map(w=>`<article><strong>${esc(w.word)}</strong><p>${esc(w.meaning)}</p></article>`).join('')}</div><label class="field-label" for="pack-test-date">Target spelling-test date<input type="date" id="pack-test-date" value="${nextTestDay()}"></label><p class="hint">Confirming starts a new spelling set with a new egg, a grey blob and new weekly choices. Your scrapbook, babies and nursery pictures stay with you. Your previous list and learning record are kept.</p><button class="primary" id="confirm-pack">Confirm these 20 · start a new set →</button><p class="feedback" id="pack-feedback" role="status"></p></section>`:''}`;}
function wordsearchPage(){return `<div class="activity-header"><button class="text-button" data-go="den">← My Secret Den</button><strong>Word Nest</strong><button class="secondary" id="replay-search">New puzzle ↻</button></div><section class="wordsearch-room"><div class="wordsearch-guide">${palMarkup(p(),{prompt:'Help me gather our weekly words for my cosy nest! Join the first and last letter. You can drag or tap twice.'})}<p id="wordsearch-status" role="status">Find all ${p().words.length} weekly words. Look across, down and diagonally. No timer.</p><div id="wordsearch-list" class="wordsearch-list"></div></div><div class="wordsearch-paper"><div class="wordsearch-scroll"><div id="wordsearch-board" role="group" aria-label="Wordsearch. Tap a first letter, then a last letter, or drag between them."></div></div><div id="search-finish" class="search-finish" hidden><h2>A lovely nest of words! ✧</h2><button class="primary" id="another-search">Make another word nest →</button></div></div></section>`;}
function portraitStats(frame){const stats=frame.stats||{},tests=stats.tests||p().testHistory.filter(r=>r.weekId===frame.weekId),tricky=stats.tricky||[];return `<section class="portrait-learning"><h3>The words we grew together</h3><div class="portrait-stat-grid"><span><strong>${frame.words.length}</strong> words all green</span><span><strong>${stats.answers??frame.words.length*6}</strong> different questions tried</span><span><strong>${tests.length}</strong> whole-list tests</span></div>${tricky.length?`<h3>Tricky words we overcame</h3><p>These needed another go. You kept practising until all six challenges were complete.</p><div class="portrait-word-list overcome">${tricky.map(w=>`<span>✧ ${esc(w)}</span>`).join('')}</div>`:'<p>All six challenges complete for every word. A little effort worth remembering.</p>'}${tests.length?`<h3>Whole-list practice tests</h3><div class="portrait-tests">${tests.map(r=>`<article><strong>${formatDay(r.date)} · ${r.score}/${r.total}</strong><p>${r.results.filter(x=>!x.correct).length?'Words for another go: '+r.results.filter(x=>!x.correct).map(x=>esc(x.word)).join(', '):'Full marks! Every word remembered.'}</p></article>`).join('')}</div>`:'<p>No whole-list test recorded for this set yet.</p>'}</section>`;}
function developerPage(){if(!developerMode)return `<section class="parent-gate"><span class="eyebrow">DEVELOPER TOOLS · SAFE TEST PLAYGROUND</span><h1>Try the whole journey.</h1><p>Open a temporary copy of this device’s progress. Make words green, earn badges, try test scores and hatch an egg. Nothing in the playground is saved over your children’s progress. Leaving or refreshing returns to real progress.</p><button class="primary" id="enter-developer">Open a test copy →</button><button class="secondary" data-go="home">Back to real play</button></section>`;const pr=p(),gate=denAccess(pr,localDay()),green=pr.words.filter(w=>wordProgress(pr,w.word)===6).length;return `<section class="page-intro"><div><span class="eyebrow">EVERYTHING BELOW USES A TEMPORARY COPY</span><h1>Spelloids test playground.</h1><p>${green}/${pr.words.length} words green · ${badgeCount(pr)} badges · ${weekAnswers(pr)} badge questions · Den ${gate.open?'open':'locked'} · ${pr.denLibrary.length} games</p></div><button class="secondary" id="reset-test-copy">Reset test copy</button></section><div class="developer-grid"><section class="settings-card"><h2>Learning & badges</h2><div class="developer-actions"><button class="secondary" data-dev="five">Add 5 correct challenges</button><button class="secondary" data-dev="one-green">Turn next word green</button><button class="secondary" data-dev="all-green">Turn every word green</button></div><div class="dev-word-grid">${pr.words.map(w=>`<span class="${wordProgress(pr,w.word)===6?'green':''}">${esc(w.word)} · ${wordProgress(pr,w.word)}/6</span>`).join('')}</div><div class="game-buttons"><button class="primary" data-go="home">See word dashboard →</button><button class="secondary" data-go="pal">Try customisation →</button></div></section><section class="settings-card"><h2>Den & weekly cycle</h2><div class="developer-actions"><button class="primary" data-dev="module">Complete one module & open Den</button><button class="secondary" data-dev="fail">Try a test with 4 wrong</button><button class="secondary" data-dev="pass">Try a test with 3 wrong</button><button class="secondary" data-dev="perfect">Try a perfect test</button><button class="primary" data-go="den">See the Den →</button><button class="secondary" id="dev-next-cycle">Start next spelling set</button></div><p class="hint">All words green or a passing whole-list test completes a cycle for the next game unlock. The first completed cycle adds Word Nest, the next adds Memory Mates, then Monster Bingo. Later cycles add remixes. A new set opens the Den again after one module is complete.</p></section><section class="settings-card"><h2>Egg, baby & wall</h2><div class="developer-actions"><button class="secondary" id="dev-egg">See current cracks</button><button class="primary" id="dev-real-hatch">Make ready & hatch</button><button class="secondary" id="dev-preview-hatch">Hatch animation only</button><button class="secondary" data-go="wall">See our nursery pictures →</button><button class="secondary" data-go="scrapbook">See the scrapbook →</button></div><p class="hint">Make ready uses real completion logic on your test copy. Then tap four times to crack the egg and meet the baby.</p></section><section class="settings-card"><h2>Clarity & character</h2><label class="field-label">Voice to compare<select id="dev-voice">${Object.entries(ALIEN_VOICES).map(([key,v])=>`<option value="${key}">${v.name}</option>`).join('')}</select></label><label class="field-label">Word from this set<select id="dev-voice-word">${pr.words.map(w=>`<option>${esc(w.word)}</option>`).join('')}</select></label><div class="developer-actions"><button class="secondary" id="dev-clear-word">♫ Slow spelling word</button><button class="secondary" id="dev-clear-question">♫ Sentence, then spell</button><button class="secondary" id="dev-chat">♫ Character greeting</button><button class="small-button" id="dev-stop">Stop audio ■</button></div><p data-voice-status class="voice-status" role="status"></p><button class="secondary" data-go="studio">Compare characters & eye rolls →</button></section></div>`;}
function beginDeveloper(){cancelSpeech();clearTemporaryMedia();developerBackup=structuredClone(state);developerMode=true;state=structuredClone(state);state.sound=false;unlockOffer=null;pausedPractice=null;creationDraft.context=null;view='developer';render();}
function leaveDeveloper(){cancelSpeech();clearTemporaryMedia();state=developerBackup;developerBackup=null;developerMode=false;unlockOffer=null;pausedPractice=null;creationDraft.context=null;demoBaby=null;chosenBaby=null;chosenPortrait=null;hatchScene=null;session=null;test=null;go('home');}
function bindV8(){
 $('#start-learning')?.addEventListener('click',()=>{const before=badgeCount(p());if(startLearning(p())){captureUnlock(before);save();render();}});
 $('#confirm-voice')?.addEventListener('click',()=>{if(chooseVoice(p(),draftForWeek().voiceStyle)){draftForWeek().voiceStyle=null;save();render();notify('Your voice is chosen for this spelling set. Choose differently next week!');}});
 $('#den-start-test')?.addEventListener('click',startTest);
 $('#pack-level')?.addEventListener('change',e=>{packLevel=e.target.value;packDraft=null;render();});
 $('#shuffle-pack')?.addEventListener('click',()=>{packDraft=randomPack(packLevel,{exclude:[...p().words.map(w=>w.word),...(packDraft||[]).map(w=>w.word)]});render();});
 $('#confirm-pack')?.addEventListener('click',()=>{try{setWeek(p(),structuredClone(packDraft),$('#pack-test-date').value,{newWeek:true});packDraft=null;selectedWord=null;save();go('home');notify('Your new words are ready. Choose to learn and earn Badge 1!');}catch(e){$('#pack-feedback').textContent=e.message;}});
 $('#enter-developer')?.addEventListener('click',beginDeveloper);$('#exit-developer')?.addEventListener('click',leaveDeveloper);
 $('#reset-test-copy')?.addEventListener('click',()=>{cancelSpeech();state=structuredClone(developerBackup);state.sound=false;creationDraft.context=null;render();});
 document.querySelectorAll('[data-dev]').forEach(b=>b.onclick=()=>{if(!developerMode)return;applyDeveloperAction(p(),b.dataset.dev);render();notify('Test copy updated. Real progress is unchanged.');});
 $('#dev-next-cycle')?.addEventListener('click',()=>{if(!developerMode)return;setWeek(p(),structuredClone(p().words),addDays(p().week.testDate,7),{newWeek:true});creationDraft.context=null;chosenPortrait=null;render();});
 $('#dev-egg')?.addEventListener('click',()=>go('egg'));
 $('#dev-real-hatch')?.addEventListener('click',()=>{if(!developerMode)return;const egg=p().eggs.find(e=>e.id===p().week.eggId);if(egg.hatched){go('egg');return;}applyDeveloperAction(p(),'all-green');beginHatch(egg.id);});
 $('#dev-preview-hatch')?.addEventListener('click',()=>beginHatch(null,true));
 const devSpeak=payload=>{cancelSpeech();guideSpeaking=false;activeVoice=$('#dev-voice').value;alienSpeaker.say(payload,activeVoice);};
 $('#dev-clear-word')?.addEventListener('click',()=>devSpeak(wordSpeech($('#dev-voice-word').value)));
 $('#dev-clear-question')?.addEventListener('click',()=>devSpeak(spellingSpeech(p().words.find(w=>w.word===$('#dev-voice-word').value))));
 $('#dev-chat')?.addEventListener('click',()=>devSpeak(VOICE_HELLO));$('#dev-stop')?.addEventListener('click',cancelSpeech);
 if(view==='play'&&['pairs','bingo'].includes(denGame?.engine)&&$('#table-game')){const weekId=p().week.id;cleanDen=mountTableGame({engine:denGame.engine,words:p().words,palName:p().palName,onWord:word=>{if(state.sound)speak(wordSpeech(word));},onFinish:result=>{(p().denHistory??=[]).unshift({...result,gameId:denGame.id,weekId,day:localDay()});save();}});$('#replay-table').onclick=()=>render();}
 if(view==='play'&&denGame?.engine==='wordsearch'&&$('#wordsearch-board')){const weekId=p().week.id;cleanDen=mountWordsearch({words:p().words,onWord:word=>{if(state.sound)speak(wordSpeech(word));},onFinish:result=>{(p().denHistory??=[]).unshift({...result,gameId:denGame.id,weekId,day:localDay()});save();}});$('#replay-search').onclick=$('#another-search').onclick=()=>render();}
}
function tableGamePage(){return `<div class="activity-header"><button class="text-button" data-go="den">← My Secret Den</button><strong>${esc(denGame.name)}</strong><button class="secondary" id="replay-table">Play again ↻</button></div><section class="table-game-room"><aside>${palMarkup(p(),{prompt:denGame.engine==='pairs'?'Let’s make some word memories! Match a word with its meaning.':'Help me fill our word bingo board! Which word matches my clue?'})}<p id="table-game-status" role="status"></p><strong class="table-game-count">Words <span id="table-game-count">0 / ${p().words.length}</span></strong></aside><div class="table-game-surface"><h2 id="table-game-round"></h2><div id="table-game"></div></div></section>`;}
function palNotice(text){const feedback=$('#creative-feedback')||$('#test-feedback')||$('#feedback');if(feedback)feedback.textContent=text;const bubble=$('.pal-dialogue');if(bubble){bubble.querySelector('p').textContent=text;bubble.querySelector('strong').textContent=p().palName+' says…';bubble.setAttribute('aria-live','polite');bubble.classList.add('gentle-reminder');}else notify(text);}
function setupLaunchMarkup(pr){const status=setupStatus(pr);return `<div class="setup-launch ${status.ready?'ready':'pending'}"><div class="setup-checklist" aria-label="Your pal’s three choices">${['name','shape','voice'].map(kind=>`<span class="${status.missing.includes(kind)?'missing':'done'}">${status.missing.includes(kind)?'○':'✓'} ${kind[0].toUpperCase()+kind.slice(1)}</span>`).join('')}</div><p id="setup-guidance" class="visually-hidden">${esc(setupMessage(pr))}</p><button class="primary" id="lets-get-spelling" ${status.ready?'':'disabled'} aria-describedby="setup-guidance">Let’s get spelling →</button></div>`;}
function paperPickerMarkup(){return `<fieldset class="paper-picker"><legend>Pick a background</legend><div class="paper-swatches">${PAPER_COLOURS.map(c=>`<button type="button" class="paper-swatch ${creativePaper===c.id?'selected':''}" data-paper="${c.id}" style="--paper:${c.value}" aria-label="${c.title} background" aria-pressed="${creativePaper===c.id}"><span></span><small>${c.title}</small></button>`).join('')}</div></fieldset>`;}
function scrapbookCard(entry){return `<article class="scrapbook-card">${entry.artId?`<img data-art-id="${esc(entry.artId)}" alt="${entry.method==='sentence'?'Your sentence: '+esc(entry.sentence):'Your picture for '+esc(entry.word)}">`:entry.image?`<img src="${esc(entry.image)}" alt="Your ${entry.method==='sentence'?'sentence':'picture'} for ${esc(entry.word)}">`:''}<small>${formatDay(entry.day)}</small><h2>${esc(entry.word)}</h2>${entry.sentence?`<p>${highlightSentenceMarkup(entry.sentence,entry.word)}</p>`:''}</article>`;}
function highlightSentenceMarkup(sentence,word){return sentenceRunsForDisplay(sentence,word).map(run=>run.highlight?`<mark>${esc(run.text)}</mark>`:esc(run.text)).join('');}
function familyScrapbookMarkup(weekId){const items=scrapbookFor(p(),weekId);return `<section class="family-scrapbook"><h3>Our spelling scrapbook</h3>${items.length?`<p>${items.length} picture${items.length===1?'':'s'} and sentence${items.length===1?'':'s'} made together.</p><div class="family-scrapbook-thumbs">${items.slice(0,3).map(x=>x.artId?`<img data-art-id="${esc(x.artId)}" alt="A scrapbook picture for ${esc(x.word)}">`:x.image?`<img src="${esc(x.image)}" alt="A scrapbook picture for ${esc(x.word)}">`:'').join('')}</div><button class="primary" data-week-scrapbook="${weekId}">Open this spelling set’s scrapbook →</button>`:'<p>No scrapbook pictures were made for this set.</p>'}</section>`;}
function archivedSetCovers(pr){return(pr.archivedCycles||[]).filter(c=>c.scrapbook?.length&&!pr.portraits.some(f=>f.weekId===c.week.id)).map(c=>`<button class="family-frame archived-set-frame" data-week-scrapbook="${c.week.id}"><div class="archived-set-cover"><span aria-hidden="true">✧</span><h3>${esc(c.look.palName)}</h3><p>${formatDay(c.week.testDate)}</p><small>This egg is still unhatched</small></div><strong>${c.scrapbook.length} scrapbook keepsakes</strong><small>A saved spelling set · tap to open</small></button>`).join('');}
function weekPreviewPage(){return homePage();}
function oldWeekPreviewPage(){return `<section class="layout-preview-note"><span class="eyebrow">LAYOUT PREVIEW · MAIN LAYOUT UNCHANGED</span><h2>Your words and practice, side by side.</h2><p>Try this at desktop or iPad width. This preview uses your current spelling list without changing progress.</p><button class="secondary" data-go="home">Back to the current layout →</button></section>`+homePage();}
function refreshSentencePreview(){clearTimeout(sentencePreviewTimer);const job=++sentencePreviewJob;sentencePreviewTimer=setTimeout(async()=>{const img=$('#sentence-preview'),input=$('#sentence');if(!img||!input)return;const src=await sentencePicture(input.value.trim()||'Your colourful sentence will appear here.', $('#sentence-font').value,{background:creativePaper,word:creativeWord});if(job===sentencePreviewJob&&img.isConnected)img.src=src;},180);}
function bindV9(){$('#prepare-list-speech')?.addEventListener('click',async()=>{const button=$('#prepare-list-speech');button.disabled=true;try{const result=await alienSpeaker.prepareWordList(p().words,selectedVoice(p()));if(result.missing.length)notify('Words still needing speech: '+result.missing.join(', '));else notify('Every spelling is ready to hear on this device.');}finally{if(button.isConnected)button.disabled=false;}});$('#retry-missing-meanings')?.addEventListener('click',retryMissingMeanings);$('#prepare-offline-voice')?.addEventListener('click',async()=>{const button=$('#prepare-offline-voice');button.disabled=true;try{await alienSpeaker.prepareOffline();}catch(error){notify(error.message);}finally{if(button.isConnected)button.disabled=false;}});
 $('#lets-get-spelling')?.addEventListener('click',()=>{if(!setupStatus(p()).ready){render();return;}pausedPractice=null;go('home');landAt($('.dashboard-intro'));});
 const applyPaper=()=>{const colour=paperColour(creativePaper),ink=paperInk(creativePaper);if($('#drawing'))$('#drawing').style.background=colour;if($('#sentence')){const input=$('#sentence');input.style.background=colour;input.style.color=ink.normal;}document.querySelectorAll('[data-paper]').forEach(b=>{b.classList.toggle('selected',b.dataset.paper===creativePaper);b.setAttribute('aria-pressed',String(b.dataset.paper===creativePaper));});};
 if(view==='creative'&&!session?.finished){applyPaper();document.querySelectorAll('[data-paper]').forEach(b=>b.onclick=()=>{creativePaper=b.dataset.paper;applyPaper();if($('#sentence'))refreshSentencePreview();});if($('#sentence')){for(const event of['input','change'])$('#sentence').addEventListener(event,refreshSentencePreview);$('#sentence-font').addEventListener('change',refreshSentencePreview);$('#starter').addEventListener('click',refreshSentencePreview);refreshSentencePreview();}}
 document.querySelectorAll('[data-week-scrapbook]').forEach(b=>b.onclick=()=>{cancelSpeech();chosenAlbumWeek=b.dataset.weekScrapbook;chosenPortrait=null;view='album';render();scrollTo({top:0,behavior:'smooth'});});

 if(view==='hatching'&&hatchScene?.phase==='reveal'&&!hatchScene.helloStarted){const scene=hatchScene;scene.helloStarted=true;const baby=$('.hatch-scene [data-pal]');if(baby)baby.dataset.reaction='hello';babyHelloTimer=setTimeout(()=>{if(hatchScene!==scene||view!=='hatching')return;if(state.sound)soundEffect('babyhello');babyHelloTimer=setTimeout(()=>{if(baby?.isConnected)baby.dataset.reaction='idle';},1200);},1400);}
}
const warmSpeech=()=>{if(state.sound)alienSpeaker.unlock();};document.addEventListener('click',warmSpeech,true);document.addEventListener('keydown',event=>{if(['Enter',' '].includes(event.key))warmSpeech();},true);
function suitSwatch(id){return id==='rainbow'?'linear-gradient(135deg,#ee8fb5,#f4ce73,#7dd4b5,#83b6ea,#b28be5)':id==='sparkly'?'radial-gradient(circle at 25% 30%,#fff4c7 2px,transparent 3px),radial-gradient(circle at 70% 65%,#fff4c7 2px,transparent 3px),#b49de0':id==='galaxy'?'linear-gradient(135deg,#262e66,#8670c6,#3c5587)':id==='aurora'?'linear-gradient(135deg,#8de0b5,#62b9ce,#c0a3e3)':id==='sunset'?'linear-gradient(135deg,#f6ce79,#ed9a94,#bd86c6)':COLOURS[id];}
function specialRewardMarkup(){const pr=p(),progress=specialProgress(pr),earned=SPECIAL_SUITS.find(s=>s.id===progress.earned);return `<section class="special-suits"><span class="eyebrow">SCRAPBOOK SPECIALS · YOURS TO KEEP</span><h2>${earned?earned.name+' unlocked!':progress.allCollected?'Your special collection is complete!':progress.target.name+' is this set’s special suit'}</h2><p>${earned?'Your next spelling set offers the next special suit. Keep creating for fun!':progress.allCollected?'Wear your favourite whenever you like.':Math.min(progress.count,10)+' / 10 scrapbook pictures or sentences. Make ten in this set to unlock it.'}</p>${!progress.complete&&!progress.allCollected?`<progress value="${Math.min(progress.count,10)}" max="10" aria-label="Scrapbook reward progress"></progress>`:''}<div class="special-suit-collection">${SPECIAL_SUITS.map(s=>`<div><button class="swatch" data-special-suit="${s.id}" style="--colour:${suitSwatch(s.id)}" aria-label="${s.name}${specialUnlocked(pr,s.id)?' · try on':' · locked'}" ${specialUnlocked(pr,s.id)&&pr.species!=='blob'?'':'disabled'}>${pr.colour===s.id?'✓':specialUnlocked(pr,s.id)?'':'🔒'}</button><small>${s.name}</small></div>`).join('')}</div><p class="hint">One new special per spelling set, across five sets. Unlocked suits can be worn now and in future weeks; your ordinary weekly colour choice stays saved.</p>${specialSuitDraft?`<div class="special-confirm"><strong>Previewing ${SPECIAL_SUITS.find(s=>s.id===specialSuitDraft)?.name}</strong>${palMarkup({...pr,colour:specialSuitDraft},{quiet:true})}<button class="primary" id="confirm-special">Wear this special suit ✓</button><button class="text-button" id="cancel-special">Keep my current look</button></div>`:''}</section>`;}
let specialSuitDraft=null;
function bindSpecialSuits(){document.querySelectorAll('[data-special-suit]').forEach(b=>b.onclick=()=>{if(specialUnlocked(p(),b.dataset.specialSuit)){specialSuitDraft=b.dataset.specialSuit;render();landAt($('.special-confirm'));}});$('#confirm-special')?.addEventListener('click',()=>{if(wearSpecialSuit(p(),specialSuitDraft)){specialSuitDraft=null;save();render();}});$('#cancel-special')?.addEventListener('click',()=>{specialSuitDraft=null;render();});}
function resultsPage(){const records=testSummary(p());return `<section class="page-intro"><div><span class="eyebrow">A LITTLE PRACTICE. LOOK AT YOUR PROGRESS.</span><h1>Your test results.</h1><p>Starting checks, practice tests and school results. Tests never earn badges or turn challenge lights green.</p></div><button class="secondary" data-go="home">Back to Spelling Hub →</button></section><div class="results-history">${records.length?records.map(r=>`<article class="result-record"><div class="result-record-heading"><span class="eyebrow">${r.type} · ${formatDay(r.date)}</span><strong>${r.score} / ${r.total}</strong></div>${Number.isFinite(r.change)?`<p class="result-change">${r.change>0?'↑ '+r.change+' more remembered':r.change===0?'The same score as your starting check':'Some words need another practice today'}${r.baselineScore!==undefined?' · starting score '+r.baselineScore+'/'+r.total:''}</p>`:''}<p>${r.wrongWords.length?'Words to practise: '+r.wrongWords.map(esc).join(', '):'Every word remembered. Lovely work!'}</p><details><summary>See every answer</summary><div class="test-results">${r.results?r.results.map(x=>`<div class="${x.correct?'correct':''}"><span>${x.correct?'✓':'↻'}</span><strong>${esc(x.word)}</strong><span>${x.correct?'Remembered':x.answer==='— skipped —'?'Skipped':esc(x.answer)}</span></div>`).join(''):(r.words||[]).map(w=>`<div class="${r.wrongWords.includes(w)?'':'correct'}"><strong>${esc(w)}</strong><span>${r.wrongWords.includes(w)?'Another go':'Remembered'}</span></div>`).join('')}</div></details>${r.notes?`<p>${esc(r.notes)}</p>`:''}</article>`).join(''):'<section class="empty-card"><h2>Your progress starts with a little go.</h2><p>A starting check is optional. You can practise first and come back when you feel ready.</p><button class="primary" id="baseline-test">Try my whole list →</button><button class="secondary" data-go="home">Start practising →</button></section>'}</div>`;}

render();launchIntro();

if('serviceWorker'in navigator&&globalThis.isSecureContext&&!globalThis.Capacitor?.isNativePlatform?.())navigator.serviceWorker.register('./sw.js').catch(()=>{});

function definitionSaveMessage(words){const s=meaningSummary(words);return 'List saved. '+s.meanings+'/'+s.total+' meanings and '+s.sentences+'/'+s.total+' example sentences. '+(s.missingMeanings.length?'Some meanings still need attention below.':'Review the suggestions below.');}
function definitionReport(words){const s=meaningSummary(words);return '<div class="definition-report '+(s.missingMeanings.length||s.missingSentences.length?'needs-attention':'')+'" role="status"><p><strong>'+s.meanings+' / '+s.total+' meanings · '+s.sentences+' / '+s.total+' example sentences</strong></p>'+(s.missingMeanings.length?'<p>Missing meanings: '+s.missingMeanings.map(esc).join(', ')+'.</p><ul>'+words.filter(w=>!w.meaning).map(w=>'<li>'+esc(w.word)+': '+esc(lookupMessage(w.lookupStatus)||'Add a simple meaning and example here.')+'</li>').join('')+'</ul><button class="secondary" id="retry-missing-meanings">Check offline glossary again</button>':'')+(s.missingSentences.length?'<p>Add an example for: '+s.missingSentences.map(esc).join(', ')+'.</p>':'')+'<p class="hint">Check that each meaning and example fits the way your child is using the word.</p></div>';}
async function retryMissingMeanings(){const active=p(),weekId=active.week?.id,targets=active.words.map(w=>w.word).join('|');try{if(parseWeeklyWords($('#words').value).join('|')!==targets){notify('Save your edited spelling list first, then retry its missing meanings.');return;}}catch(error){notify(error.message);return;}if(!saveEditor())return;save();const button=$('#retry-missing-meanings');if(button)button.disabled=true;try{const suggestions=await suggestWordList(active.words.map(w=>w.word),active.words);if(active.week?.id!==weekId||active.words.map(w=>w.word).join('|')!==targets)return;active.words=suggestions;syncEgg(active);save();if(view==='parents'&&p()===active){render();notify(definitionSaveMessage(active.words));}}finally{if(button?.isConnected)button.disabled=false;}}
